Ceviri.ekle("hy","olay",{
"OLAYLAR_EK:1600-10-20:0":{"b": ["Կանիժայի նվաճումը", "0c7b6aa3"], "d": ["Երկարատև պատերազմի ժամանակ գրավվեց Կանիժան. հաջորդ տարի Թիրյաքի Հասան փաշայի պաշտպանությունը դարձավ լեգենդար։", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["Սկսվեց Ույվարի արշավանքը — Ֆազըլ Ահմեդ փաշան Էդիրնեից շարժվեց Ավստրիայի դեմ", "306a86db"], "d": ["Երբ Ավստրիան հարձակվեց Տրանսիլվանիայի վրա և գրավեց Székelyhíd և Կոլոժվար ամրոցները, Ստամբուլը որոշեց արշավանքի ելնել Հաբսբուրգների դեմ։ Մեծ վեզիր Քյոփրյուլյուզադե Ֆազըլ Ահմեդ փաշան 1663 թվականի ապրիլի 13-ին շարժվեց Էդիրնեից։ Բելգրադում եկավ Ավստրիայի խաղաղության խնդրանքը, սակայն Օսիեկում երկու հանդիպման ընթացքում օսմանյան պայմանները մերժվեցին։ Բուդայում անցկացված խորհրդակցության ժամանակ ևս որպես թիրախ որոշվեց Ույվարը։", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Ույվարի նվաճումը", "ce289470"], "d": ["Գրավվեց Հյուսիսային Հունգարիայի բանալի ամրոցը՝ Ույվարը (Նովե Զամկի). «ուժեղ, ինչպես թուրքը Ույվարի մոտ» ասացվածքը անցավ եվրոպական լեզուներ։ Ույվարից հետո կարճ դիմադրությունից հանձնվեցին նաև Նիտրան և Լևան. երկուսն էլ 1664 թվականի գարնանը հետ վերցրեց դը Սուշը (De Souches)։", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Մորեայի հետգրավումը", "9b6460f1"], "d": ["Կառլովիցով Վենետիկին թողնված Մորեան մեկ անգամից հետ վերցվեց։ Նույն ամսաթվին միացած այլ վայրեր՝ Բալյաբադրա (Պատրաս), Լեպանտո։", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Բելգրադի երկրորդ կորուստը — արքայազն Եվգենիի պաշարումը", "6a194354"], "d": ["Վարադինի ջախջախումից և Տեմեշվարի կորստից հետո արքայազն Եվգենին պաշարեց Բելգրադը. քաղաքը փրկելու եկած օգնական բանակի պարտությունից հետո ամրոցը հանձնվեց։ Կառլովիցից հետո 1690 թվականին հետ վերցված քաղաքը այսպիսով կրկին ձեռքից գնաց, և Դանուբի պաշտպանության գիծը փլուզվեց։ Բելգրադը կարող էր հետ վերցվել միայն քսաներկու տարի անց՝ 1739 թվականի Բելգրադի պայմանագրով։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Սմեդերևո։ Ատլասը նաև Հիսարջըքի (Գրոցկա) և Յագոդինայի (Jagodina) շրջանները այս օրը գրում է Հաբսբուրգների կողմում (շրջանի օրը. բնակավայրի մակարդակով օրը աղբյուրում նշված չէ, հայտարարված մոտավորություն). իսկ Մեհադիան Հաբսբուրգներին է անցնում 1717 թվականի օգոստոսի 27 ամսաթվով (Bánlaky 0019/1715)։", "83c63cd6"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Օչակովի (Օզի) անկումը", "90a67a6c"], "d": ["Սև ծովից հյուսիս գտնվող բանալի ամրոց Օչակովը արյունալի գրոհով անցավ Ռուսաստանի ձեռքը. քաղաքի բնակչությունը սրի անցկացվեց։", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Բուխարեստի պայմանագիրը — Բեսարաբիայի կորուստը", "932da4d6"], "d": ["1806-1812 թվականների ռուսական պատերազմին վերջ դրած պայմանագրով Պրուտից արևելք ընկած տարածքը (Բեսարաբիան) թողնվեց Ռուսաստանին։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Ակկերման, Կիլիա, Խոթին, Բենդեր, Իզմաիլ։ Ատլասը նաև Բեսարաբիայի ներսում գտնվող Քիշնևը (Chișinău), Բելցին (Bălți), Կահուլը (Cahul) և Օրհեյը (Orhei) նույն օրը համարում է Մոլդովայից (օսմանյան վասալ) Ռուսաստանին անցած։ Սորոկան (Soroca) ևս նույն օրն անցնում է Ռուսաստանին։", "b5921c60"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Ադրիանապոլսի պայմանագիրը", "b3a8fe4c"], "d": ["Ռուսական բանակի՝ Էդիրնե մտած պատերազմի վերջում կորսվեց Դանուբի դելտան. փաստացի ընդունվեց Հունաստանի ինքնավարությունը/անկախությունը։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Բրաիլա, Անապա, Ախալցխա։ Թեև պայմանագիրը հողը վերադարձրեց, օկուպացիան անմիջապես չավարտեց. Վալախիան, Մոլդովան և Սիլիստրան, մինչև ռազմատուգանքի վճարումը, որպես գրավ մնացին ռուսական կառավարման տակ. այս պատճառով է, որ քարտեզում այդ վայրերը 1829 թվականից հետո ևս երևում են օկուպացիայի տակ։ Այս պայմանագրով ավարտվեց նաև օսմանյան հավակնությունը Չերքեզիայի (Մայկոպ) և չերքեզական ափի (Սոչի, Տուապսե) նկատմամբ. ափը հետագայում անցավ Ռուսաստանին (Սոչի և Տուապսե՝ 1838)։", "5666619b"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Սերբիային ինքնավարության ֆերմանը — ժառանգական կնյազություն և կայազորի պայմանը", "6a5d901d"], "d": ["Ադրիանապոլսի պայմանագրի՝ Սերբիային վերաբերող դրույթի համաձայն տրված խաթթ-ը հյումայունը Միլոշ Օբրենովիչին ճանաչեց ժառանգական կնյազ և Սերբիան դարձրեց ներքին գործերում ազատ, արտաքուստ օսմանցիներին ենթակա ինքնավար իշխանապետություն։ Դրույթները. կնյազությունը անցնելու էր հորից որդուն, տարեկան հարկը վճարվելու էր հաստատուն չափով, սերբական ժողովը ստեղծելու էր իր ներքին կառավարումը, եկեղեցին լինելու էր ինքնավար. փոխարենը Բելգրադի, Սմեդերևոյի, Շաբացի, Բյոյուրդելենի և Ֆեթհյուլիսլամի ամրոցներում մնալու էին օսմանյան կայազորներ։ Այս երկակի կառույցը տևեց մինչև 1867 թվականին կայազորների դուրսբերումը։ Քարտեզում Բելգրադ քաղաքը այս ամսաթվին միանում է ինքնավար Սերբիային. Կալեմեգդան ամրոցը մինչև 1867 թվականը ցույց է տրվում օսմանյան կայազորի ձեռքում։", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Կիպրոսի թողնվելը անգլիական կառավարմանը", "423da3ee"], "d": ["Ռուսական սպառնալիքի դեմ դաշինքի դիմաց Կիպրոսի կառավարումը փոխանցվեց Անգլիային. իրավաբանորեն այն մնաց օսմանյան հող։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Նիկոսիա, Ֆամագուստա, Կիրենիա, Լիմասոլ, Լառնակա (Թուզլա), Պաֆոս, Գյուզելյուրթ (Morphou), Ակրոտիրի, Եպիսկոպի, Դիկելյա (Dhekelia). այսինքն՝ ամբողջ կղզին։", "d1abea1c"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Թեսալիայի թողնվելը Հունաստանին", "ac614d24"], "d": ["Բեռլինի վեհաժողովի որոշումների համաձայն՝ Թեսալիան և Արտայի շրջակայքը փոխանցվեցին Հունաստանին։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Արտա, Ենիշեհիր (Լարիսա), Տիրհալա, Իզդին (Լամիա)։ Այս փոխանցմամբ Վոլոսը (Golos), Կալաբական և Կարդիցան (Թեսալիա) անցան Հունաստանին։", "9fc28546"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Արևելյան Ռումելիի միացումը Բուլղարիային", "ee43f137"], "d": ["Արևելյան Ռումելիի ինքնավար վիլայեթը հեղաշրջմամբ միացվեց Բուլղարիային. Բարձր Դուռը ընդունեց կատարված փաստը։ Այս միավորմամբ Արևելյան Ռումելիի ամբողջ տարածքը (Էսքի Զաղրա, Թաթարփազարջըղ, Իսլիմիե, Հասքյոյ, Բուրգաս, Այդոս, Էլխովո) անցավ Բուլղարիայի իշխանապետությանը։", "7fe3cc42"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Դոմոկոսի (Դյոմեքե) դաշտային ճակատամարտը", "9c6f29a5"], "d": ["1897 թվականի օսմանա-հունական պատերազմում բանակը Դոմոկոսի մոտ վճռական հաղթանակ տարավ. դիվանագիտական ճնշման պատճառով հողային ձեռքբերումը մնաց սահմանափակ։", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Ինքնավարություն Կրետեին", "2e764881"], "d": ["Թեև օսմանա-հունական պատերազմն ավարտվեց օսմանյան հաղթանակով, Անգլիան, Ռուսաստանը, Ֆրանսիան և Իտալիան 1897 թվականի դեկտեմբերի 18-ին հռչակեցին Կրետեի ինքնավարությունը. կղզին օսմանյան տիրապետության ներքո լինելու էր չեզոք և ինքնավար վիլայեթ։ 1898 թվականի նոյեմբերի 6-ից հետո Կանդիայում և Կիսամոյում թուրքական դրոշն այլևս չբարձրացվեց. Հունաստանի թագավորի որդի արքայազն Գեորգիի՝ որպես արտակարգ գերագույն կոմիսար 1898 թվականի դեկտեմբերի 22-ին պաշտոնի անցնելով Կրետեն փաստացի դուրս եկավ օսմանյան կառավարումից (պաշտոնապես անջատվեց 1913 թվականին)։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Կանդիա (Կրետե), Խանիա։", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Բուլղարիայի անկախությունը և Բոսնիայի բռնակցումը", "393feaa4"], "d": ["Սահմանադրական շրջանի խառնակության մեջ Բուլղարիան հռչակեց իր անկախությունը, Ավստրո-Հունգարիան բռնակցեց Բոսնիա և Հերցեգովինան։ Այս հռչակմամբ Բուլղարիայի իշխանապետության բոլոր հողերը (Վառնա, Շումեն, Ռուսչուկ, Բուրգաս, Իսլիմիե և այլն) դարձան անկախ Բուլղարիայի թագավորություն։", "b7f0bb26"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Էդիրնեի հետգրավումը", "536e5599"], "d": ["Բալկանյան երկրորդ պատերազմում բանակը, անցնելով Մարիցան, առանց կռվի հետ վերցրեց Էդիրնեն։ Նույն ամսաթվին միացած այլ վայրեր՝ Քըրքլարելի, Թեքիրդաղ։", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Քութի (Kûtülamâre) հաղթանակը", "98b972bc"], "d": ["Քութում պաշարված անգլիական դիվիզիան իր հրամանատարով և 13 հազար զինվորով հանձնվեց. Առաջին համաշխարհային պատերազմի օսմանյան ամենամեծ հաղթանակներից մեկը։", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Բաղդադի կորուստը", "2c18a816"], "d": ["383 տարի օսմանյան եղած Բաղդադը անցավ անգլիական բանակին։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Քերբելա, Քըզըլռուբաթ։", "880969bf"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Երուսաղեմի կորուստը", "94067617"], "d": ["401 տարի օսմանյան եղած Երուսաղեմը հանձնվեց՝ առանց պաշտպանվել կարողանալու։", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Դամասկոսի կորուստը", "ed177b68"], "d": ["Պաղեստինի ճակատի փլուզմամբ Դամասկոսը դատարկվեց. Սիրիայում չորսդարյա օսմանյան կառավարումն ավարտվեց։ Նույն ամսաթվին ձեռքից դուրս եկած այլ բնակավայրեր՝ Համա, Հոմս։", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Մեդինայի հանձնումը", "76b505f6"], "d": ["Զինադադարից 72 օր անց «Անապատի վագր» Ֆահրեդդին փաշայի դիմադրությունն ավարտվեց փադիշահի հրամանով. Հիջազում վերջին օսմանյան զորամասը վայր դրեց զենքը։", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Իզմիրի օկուպացիան", "e32e5e77"], "d": ["Հունական բանակը ափ իջավ Իզմիրում. առաջին գնդակով սկսված դիմադրությունը վառեց Ազգային պայքարի պատրույգը։ Իսկ Այդընը օկուպացվեց 1919 թվականի մայիսի 27-ին (առանձին գրառում)։", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Ստամբուլի պաշտոնական օկուպացիան", "a8e98ada"], "d": ["Անտանտի ուժերը պաշտոնապես օկուպացրին Ստամբուլը, Մեբուսանների ժողովը ցրվեց. պատգամավորները շարժվեցին դեպի Անկարա։", "09ed005b"]},
"OLAYLAR_H7_ASAMA:1529-05-10:0":{"b": ["Կանունիի մեկնումը Վիեննայի արշավանքի — Հաբսբուրգյան պատերազմը կրկին սկսվեց", "f7afd2a9"], "d": ["Մոհաչից հետո Հունգարիայի գահը երկատվել էր. Ֆերդինանդը 1527 թ. վերցրել էր Բուդան և Զապոյայիին հանել մայրաքաղաքից։ Փադիշահը Զապոյայիին աջակցելու և Հաբսբուրգների առաջխաղացումը կասեցնելու համար չորրորդ անգամ մեկնեց արշավանքի. արշավանքից առաջ մեծ վեզիր Իբրահիմ փաշային շնորհվեցին սերասքերի կոչումը և Ռումելիի բեյլերբեյությունը, ամբողջ ծրագրումը կատարվեց նրա հետ։ Ճանապարհին հորդառատ անձրևները հետաձգեցին բանակի առաջխաղացումը. արշավանքը շարունակվեց Բուդան վերցնելով և Զապոյայիին հանձնելով ու Վիեննայի պաշարումով։", "4d80633a"]},
"OLAYLAR_H7_ASAMA:1562-05-05:0":{"b": ["Հաբսբուրգների հետ խաղաղության նորոգումը — Տրանսիլվանիայի և Թեմեշվարի պատերազմի ավարտը", "97071975"], "d": ["1551 թ. Տրանսիլվանիայի՝ Ֆերդինանդին անցնելով սկսված և Թեմեշվարի գրավումով, Էգերի պաշարումով ու նման արշավանքներով շարունակված պատերազմը փակվեց Հաբսբուրգների հետ խաղաղությունը շարունակելու որոշմամբ։ Համաձայնագիրը փոխադարձաբար նորոգում էր երկու կողմերի հին պարտավորությունները, սակայն սահմանամերձ խառնաշփոթներին լուծում չտվեց, և 1564 թ. Ֆերդինանդի մահից հետո Տրանսիլվանիայի իրադարձությունները կրկին սրվեցին։", "04cfeca8"]},
"OLAYLAR_H7_ASAMA:1566-05-01:0":{"b": ["Կանունիի վերջին արշավանքը — մեկնումը Ստամբուլից՝ Սիգետվարի և Էգերի նպատակով", "31277d21"], "d": ["1564 թ. Ֆերդինանդի մահից և Մաքսիմիլիան II-ի գահ բարձրանալուց հետո Տրանսիլվանիայի սահմանին բախումները շատացել էին։ Ծեր փադիշահի՝ Սոքոլլու Մեհմեդ փաշայի հետ ծրագրած արշավանքում թիրախները լինելու էին Սիգետվարի և Էգերի ամրոցները, իսկ կայսրին էլ պետք էր սպառնալիքով զգուշացնել։ Էյուփ Սուլթանի դամբարանում աղոթելուց հետո նա մեծ հանդիսությամբ հեռացավ Ստամբուլից. մայիսի 15-ին հասավ Էդիրնե, իսկ ճանապարհ ընկնելու հիսուներորդ օրը՝ Բելգրադ։ Սա նրա վերջին մեկնումն էր մայրաքաղաքից, որը նա այլևս չէր տեսնելու։", "c601608a"]},
"OLAYLAR_H7_ASAMA:1568-02-17:0":{"b": ["Էդիրնեի պայմանագիրը — Հաբսբուրգների հետ պատերազմական վիճակի ավարտը", "d08883e3"], "d": ["Սիգետվարի արշավանքից հետո Էդիրնեում ձմեռող Սելիմ II-ի մոտ էին գտնվում Հաբսբուրգների, Սեֆյանների, լեհերի, ֆրանսիացիների և Վենետիկի դեսպանները։ Որոշվեց շարունակել խաղաղությունը Սեֆյանների հետ, և ստորագրվեց Հաբսբուրգների հետ պատերազմական վիճակին վերջ դնող պայմանագիրը։ Այս գործերում մեծ էր մեծ վեզիր Սոքոլլու Մեհմեդ փաշայի ազդեցությունը։", "27b65c0e"]},
"OLAYLAR_H7_ASAMA:1604-06-15:0":{"b": ["Ջիղալազադե Սինան փաշան մեկնեց Իրանի արշավանքի", "1e90763e"], "d": ["Մինչ Իրանի և Ավստրիայի հետ երկու ճակատով պատերազմը շարունակվում էր, Շահ Աբբասը պաշարելով վերցրել էր Երևանը, մտել Կարս, բայց միայն Ախալցխայի մոտ էր հնարավոր եղել կանգնեցնել նրան։ Արևելքի սերդար նշանակված Ջիղալազադե Սինան փաշան ուշացումով շարժվեց Ստամբուլից և նոյեմբերի 8-ին հասավ Կարսի մատույցները։ Թեև իրավիճակը նպաստավոր էր, նա չգնաց շահի դեմ, այլ ձմեռեց Վանում, իսկ շահի հարձակման պատճառով անցավ Էրզրում. արշավանքային մեկ եղանակն իզուր անցավ։", "d155e6f3"]},
"OLAYLAR_H7_ASAMA:1605-11-06:0":{"b": ["Ջիղալազադե Սինան փաշայի պարտությունը Ուրմիա լճի մոտ (Սուֆիյան)", "7438fec4"], "d": ["1605 թ. արշավանքային եղանակին Թավրիզը վերստանալու համար շարժվող Սինան փաշայի դրությունը ցնցվեց, երբ Էրզրումի բեյլերբեյ Քյոսե Սեֆեր փաշան, հիմնական բանակից առանձին գործելով, գերի ընկավ։ Շահ Աբբասի հանկարծակի հարձակումը Ուրմիա լճի շրջակայքում ծանր պարտություն պատճառեց բանակին. Սինան փաշան նախ նահանջեց Վան, ապա՝ Դիարբեքիր։ Օգնության ուշանալու մեղադրանքով Հալեպի բեյլերբեյ Ջանբոլաթօղլու Հյուսեյին փաշային մահապատժի ենթարկելը Անատոլիայում մեծ ապստամբություն բռնկեց. Սինան փաշայի մահից հետո Շահ Աբբասը վերցրեց Գանձակը, Շիրվանը և Շամախին։", "8e130829"]},
"OLAYLAR_H7_ASAMA:1610-03-26:0":{"b": ["Քույուջու Մուրադ փաշայի Թավրիզի արշավանքը — Աջըչայում բախում տեղի չունեցավ", "3c0a0a5d"], "d": ["Ջելալիների ապստամբությունները ճնշած և Անատոլիայում անդորրը վերականգնած մեծ վեզիր Քույուջու Մուրադ փաշան Էրզրումի, Հասանկալեի, Չալդըրանի և Խոյի ճանապարհով շարժվեց Շահ Աբբասի դեմ, որի՝ Թավրիզում սպասելու լուրն էր ստացվել։ Երկու բանակները Թավրիզից հյուսիս՝ Աջըչայ վայրում, դեմ հանդիման կանգնեցին, բայց ճակատամարտ տեղի չունեցավ. նամակագրությունը շարունակվեց։ Ձմռան մոտենալու, ռազմամթերքի և պարենի սղության պատճառով փաշան Խլաթի, Վանի և Բիթլիսի վրայով նահանջեց Դիարբեքիր և հաջորդ ամառ, մինչ նոր արշավանքի էր պատրաստվում, այնտեղ մահացավ (1611 թ. օգոստոսի 5)։", "289fa3b6"]},
"OLAYLAR_H7_ASAMA:1615-04-23:0":{"b": ["Օսմանա-սեֆյան պատերազմը կրկին սկսվեց — մեծ վեզիր Օքյուզ Մեհմեդ փաշան մեկնեց Արևելյան արշավանքի", "ef32fa31"], "d": ["1612 թ. Նասուհ փաշայի պայմանագրից հետո Իրան դեսպան ուղարկված Ինջիլի Մուստաֆա չավուշից լուր չստացվելու պատճառով մեծ վեզիր Մեհմեդ փաշան նշանակվեց Արևելյան արշավանքի, ավարտեց պատրաստությունները և անցավ Ուսկյուդար։ Հենց ճանապարհ ընկնելու պահին եկավ լուրը, որ Ինջիլի չավուշը և Իրանի դեսպան Բուրուն Քասըմ խանը համաձայնագրով ու նվերներով հասել են Վան, սակայն արշավանքը չհետաձգվեց։ Մեծ վեզիրը ձմեռը անցկացրեց Հալեպում։", "5c279a1a"]},
"OLAYLAR_H7_ASAMA:1616-09-12:0":{"b": ["Երևանի պաշարումը — հիսունհինգ օր անց վերացվեց անարդյունք", "64a4ecb6"], "d": ["1616 թ. ապրիլին Հալեպից մեծ բանակով դուրս եկած մեծ վեզիրը Էրզրում-Կարս ճանապարհով հասավ Երևանի մատույցները։ Կարծելով, թե ամրոցը հեշտությամբ կհանձնվի, ծանր թնդանոթներ չէին բերվել. պաշարումը պաշարման նյութերի պակասի պայմաններում տևեց հիսունհինգ օր։ Ենիչերիների աղա Մուսլու աղայի և Թեքելի Մեհմեդ փաշայի նահատակվելու, զորքի դժկամության և եղանակի առաջանալու պատճառով պաշարումը վերացվեց, և բանակը նահանջեց Էրզրում։ 1616 թ. նոյեմբերին Մեհմեդ փաշան հեռացվեց պաշտոնից, նրա փոխարեն եկավ Խալիլ փաշան։", "823b20af"]},
"OLAYLAR_H7_ASAMA:1618-09-10:0":{"b": ["Սերավի (Պուլի Շիքեստե) պարտությունը — Խալիլ փաշայի Իրանի արշավանքը", "d323ed03"], "d": ["Օքյուզ Մեհմեդ փաշայի փոխարեն սերդար դարձած Խալիլ փաշան 1618 թ. կրկին շարժվեց Իրանի դեմ։ Թավրիզի և Արդաբիլի միջև՝ Պուլի Շիքեստե վայրում, տեղի ունեցած ճակատամարտը ավարտվեց օսմանյան բանակի պարտությամբ։ Աղբյուրներում Սերավի ճակատամարտ անվամբ նույնպես հիշատակվող այս պարտությունից հետո նույն ամսին ստորագրվեց Սերավի պայմանագիրը։", "f2c187de"]},
"OLAYLAR_H7_ASAMA:1700-01-01:0":{"b": ["Լեպանտոն Կառլովիցի համաձայն վերադարձվեց Օսմանյան պետությանը", "9ca4f9dd"], "d": ["1683-1699 թվականների պատերազմների ընթացքում երկար դիմադրելուց հետո 1687 թ. հուլիսին իր շրջակա ամրոցների հետ Վենետիկի ձեռքն ընկած Լեպանտոն Կառլովիցի պայմանագրից մեկ տարի անց էլ մնաց վենետիկցիների ձեռքում, ապա վերադարձավ Օսմանյան պետությանը։ Այսպիսով Կորնթոսի ծոցի մուտքի մոտ գտնվող ամրոցը օսմանյան վարչությանը վերադարձավ Մորեայից տասնհինգ տարի շուտ։", "782654b8"]},
"OLAYLAR_H7_ASAMA:1733-07-19:0":{"b": ["Թոփալ Օսման փաշան Դուջումում հաղթեց Նադիրին — Բաղդադի պաշարումը վերացվեց", "7ae1fc9e"], "d": ["1733 թ. հունվարին Բաղդադը պաշարած Նադիրի դեմ Բաղդադին օգնության ուղարկված Թոփալ Օսման փաշայի հրամանատարությամբ բանակը Սամառայի մոտ գտնվող Դուջումում ջախջախեց Նադիրի ուժերը. վիրավորված Նադիրը նահանջեց Համադան, և ամիսներ տևած պաշարումը վերացվեց։ Սակայն հաղթանակը կարճ տևեց. նույն տարվա վերջին Նադիրը կրկին մտավ Իրաք և Կիրկուկից հյուսիս՝ Աքդերբենդում, հաղթեց օսմանյան ուժերին. Թոփալ Օսման փաշան այդ կռիվների ընթացքում կյանքը կորցրեց և թաղվեց Կիրկուկում։", "6444aec6"]},
"OLAYLAR_H7_ASAMA:1743-02-25:0":{"b": ["Նադիր շահի Իրաքի արշավանքը — սկսվեց օսմանա-իրանական վերջին պատերազմը, Կիրկուկն ընկավ", "ba014bf5"], "d": ["Դաղստանում և Վրաստանում տասնութ ամիս մնացած Նադիր շահը, որի՝ ջաֆարիությունը որպես հինգերորդ մազհաբ ճանաչելու պահանջը օսմանցիները մերժել էին, 1743 թ. նոր արշավանք սկսեց օսմանցիների դեմ և մեծ բանակով մտավ Կիրկուկ։ Նույն հաջողությունը Մոսուլում ցույց տալ չկարողացավ. ստիպված եղավ վերացնել պաշարումը։ Այս պատերազմը 1746 թ. Քերդենի պայմանագրով ավարտված օսմանա-իրանական վերջին պատերազմն է։", "5515afec"]},
"OLAYLAR_H7_ASAMA:1744-07-29:0":{"b": ["Նադիր շահի կողմից Կարսի պաշարումը — տևեց երկու ամիս, արդյունք չտվեց", "a3ea61d9"], "d": ["Օսմանցիներին ապաստանած սեֆյան արքայազն Սաֆի Միրզան հավակնում էր Իրանի գահին. ըստ ծրագրի՝ Կարսի սերասքերը նրան Թավրիզի վրայով պետք է տաներ Սպահան և գահ բարձրացներ, իսկ օսմանցիները Իրանի դեմ երեք ճակատ էին բացել։ Դրան ի պատասխան Նադիր շահը շարժվեց դեպի Կարս և պաշարեց ամրոցը։ Երկու ամիս տևած պաշարումից արդյունք չունեցավ։", "42fc48b5"]},
"OLAYLAR_H7_ASAMA:1745-08-21:0":{"b": ["Կաղավերդի պարտությունը — Եղեն Մեհմեդ փաշայի բանակը ցրվեց", "7caf6f22"], "d": ["Կարսի պաշարման հաջորդ տարում Նադիր շահը Կաղավերդ վայրում ջախջախեց Եղեն Մեհմեդ փաշայի ղեկավարած օսմանյան ուժերը։ Այնուհետև վերադարձավ Սպահան։ Ջաֆարիության ճանաչման հարցում իր պնդումից հրաժարվելը հաջորդ տարի բացեց Քերդենի պայմանագրի ճանապարհը։", "3992b8ed"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["Սաուդյան-վահաբիական ուժերի կողմից Հայիլի ամիրայության գրավումը. կառավարումը Աբդե ցեղի Իբն Ալի ընտանիքի ձեռքում էր", "2d29ceb9"], "d": ["Երբ Առաջին սաուդյան պետության ուժերը գրավեցին Հայիլի ամիրայությունը, քաղաքի կառավարումը Շամմար ցեղի Աբդե տոհմի Իբն Ալի ընտանիքի ձեռքում էր։ Այս ընտանիքը Հայիլը կառավարեց մինչև 1835 թ., երբ Աբդուլլահ բ. Ռաշիդը զավթեց ամիրայությունը. Ռաշիդյան հարստությունը հիմնվեց միայն այդ ժամանակ։ Ատլասում մինչ այսօր Հայիլը մինչև 1836 թ. երևում էր անտեր, մինչդեռ աղբյուրը 1820 թ. համար նշում է քաղաքի ամիրի անունը։", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["Կվառների կղզիների անցումը Նապոլեոնի Իտալիայի թագավորությանը, Կոտորի ծոցի անցումը ռուսական կառավարման տակ", "c5e411c8"], "d": ["Պրեսբուրգի պայմանագրից հետո Կվառների կղզիները, ի տարբերություն Դալմաթիայի, ոչ թե անմիջականորեն Ֆրանսիային, այլ Նապոլեոնի Իտալիայի թագավորությանը միացվեցին. նրանք Իլիրական նահանգների մեջ մտան միայն 1809 թ.։ Կոտորի ծոցում (Բոկա Կոտորսկա) ավստրիական կառավարումն ավարտվեց, և 1806-1807 թթ. հաստատվեց ռուսական կառավարում. Բոկան Ֆրանսիային անցավ միայն 1807 թ.։ Այս երկու տարբերակումը հնարավոր չէ արտացոլել ատլասի մեկ միասնական «Ֆրանսիա» պատուհանով։", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["Դալմաթիայի անցումը ֆրանսիական կառավարման տակ. Պրեսբուրգի (Բրատիսլավա) պայմանագրի կիրարկումը", "00bfe4f6"], "d": ["1805 թ. դեկտեմբերի 26-ի Պրեսբուրգի (Բրատիսլավա/Pressburg) պայմանագիրը Ավստրիային ստիպեց հրաժարվել Իստրիայից, Դալմաթիայից և Ադրիատիկի բոլոր կղզիներից։ Ֆրանսիան փաստացի ստանձնեց կառավարումը 1806 թ. փետրվարին. Զադարը մնաց գլխավոր պրովեդիտորի նստավայրը, և 1806-1810 թթ. այդ պաշտոնը վարեց վենետիկցի Վիչենցո Դանդոլոն։ 1809 թ. Շյոնբրունի պայմանագրից հետո Դալմաթիան միացավ Իլիրական նահանգներին։ Այսպիսով, ավարտվեց 1797 թ. ի վեր տևած առաջին ավստրիական կառավարումը. ատլասում մինչ այսօր այդ ժամանակաշրջանը երևում էր որպես անընդմեջ ավստրիական։", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["Ավստրիան վերագրավում է Իլիրական նահանգներն ու Դալմաթիան. նապոլեոնյան կառավարման վախճանը", "1b2ac942"], "d": ["1813 թ. վերջում Հաբսբուրգների զորամասերը հետ գրավեցին Սավայից հարավ ընկած շրջանը, և վերականգնվեց հին սահմանային կազմակերպությունը. ավստրիական բանակը 1813 թ. հոկտեմբերին մտավ Իստրիա։ Կառլովացը այդ ժամանակից դարձավ Ավստրիայի Իլիրական թագավորության մաս։ Ֆրանսիական կառավարման շրջանը Դալմաթիայում նույնպես փակվեց 1813 թ.։ Շրջանի պատկանելությունը Ավստրիային պաշտոնապես հաստատվեց 1814 թ. Փարիզի խաղաղությամբ և 1815 թ. Վիեննայի վեհաժողովի որոշումներով։ Այս գործողությամբ Վիլլախը, Տարվիսը, Գյորցը, Գրադիսկան և Պուլան (Իլիրական նահանգներ) 1813 թ. վերջում վերադարձան Ավստրիային։", "bf1e49a8"]},
"OLAYLAR_MISIR1801:1801-05-14:0":{"b": ["Դամիետի խլումը ֆրանսիացիներից. Լեսբե ամրոցի դատարկումը", "06b1e7b0"], "d": ["Մեծ վեզիրի բանակից Իբրահիմ փաշայի հրամանատարությամբ մի ուժ ուղարկվեց Դամիետ։ Մայիսի 14-ի առավոտյան, երբ պատրաստվել էր գրոհ Դամիետը պաշտպանող Լեսբե ամրոցի վրա, պարզվեց, որ ֆրանսիացիները դատարկել են ամրոցը, և կայազորը հեռացել է. գրավվեցին նաև նրան ենթակա երկու փոքր ամրոցները։ Ապրիլին ընկած Ռոզետտայից հետո Դամիետը դարձավ Նեղոսի գետաբերանի երկրորդ քաղաքը, որ դուրս եկավ ֆրանսիական վերահսկողությունից։", "2eb4936c"]},
"OLAYLAR_MISIR1801:1801-06-27:0":{"b": ["Կահիրեի ընդունումը ֆրանսիացիներից. Բելիարի կապիտուլյացիան", "7a11bb5e"], "d": ["Օսմանյան և բրիտանական ուժերի՝ դեպի Եգիպտոս ուղղված համատեղ գործողության ընթացքում Կահիրեում գտնվող ֆրանսիական ուժերի հրամանատար գեներալ Բելիարը ստորագրեց կապիտուլյացիան։ Կահիրեի հետ միասին ֆրանսիական վերահսկողությունից դուրս եկավ նաև Սուեզը, որ ֆրանսիացիները գրավել էին 1798 թվականի նոյեմբերին։ Օկուպացիայի փակումն ավարտվելու էր երկու ամիս անց Ալեքսանդրիայում, իսկ երկրից էվակուացիան տևելու էր մինչև հոկտեմբեր։", "e8dac3f4"]},
"OLAYLAR_MISIR1801:1801-08-31:0":{"b": ["Ալեքսանդրիայի ընդունումը ֆրանսիացիներից. Մենուի կապիտուլյացիան", "cd50663c"], "d": ["Արևելյան բանակի գլխավոր հրամանատար գեներալ Մենուն օգոստոսի 17-ին պաշարվեց Ալեքսանդրիայում. օգոստոսի 21-ին անգլիացիները գրավեցին քաղաքի մոտ գտնվող Մարաբուտ ամրոցը, իսկ օգոստոսի 31-ին Մենուն ստորագրեց բանակի կապիտուլյացիան։ Ֆրանսիական զորամասերի վերադարձը Ֆրանսիա սկսվեց սեպտեմբերի 2-ին։ Այսպիսով 1798 թվականի հունիսին Ալեքսանդրիայում ափ իջնելով սկսված օկուպացիան ավարտվեց այն քաղաքում, որտեղ սկսվել էր։", "22e807c1"]},
"OLAYLAR_OK106:1571-01-01:0":{"b": ["Լեհաստանի Դնեպրի գծի առաջ մղումը — Կրեմենչուգի հիմնադրումը", "1bc86966"], "d": ["Լեհա-Լիտվական պետությունը Դնեպրի միջին հոսանքի հանգուցակետում, որը Ղրիմի արշավանքների անցման վայր էր, հիմնեց սահմանային նոր ավան. քսանհինգ տարի անց այնտեղ ավելացվեց նաև ամրոց։ Այսպիսով Լեհաստանի վերահսկողության գիծը իջավ մինչև Զապորոժիեի տափաստանի հյուսիսային եզրը, և գետի այս անցումը առաջին անգամ կապվեց որևէ պետության մշտական կայազորի հետ։ Հաջորդ դարում ավանը որպես կազակական գնդի կենտրոն պետք է անցներ հեթմանության կարգի մեջ։", "4d022f2b"]},
"OLAYLAR_OK106:1616-01-01:0":{"b": ["Ումանի հայտնվելը Լեհաստանի Եդիսանի սահմանագծում", "2e6551ab"], "d": ["Ումանը առաջին անգամ հիշատակվեց փաստաթղթերում որպես Լեհաստանի վարչության ներքո գտնվող Բրացլավի տարածաշրջանի հարավ-արևելյան ծայրի բնակավայր։ Այն գտնվում էր Ղրիմի խանության՝ դեպի հյուսիս ձգվող արշավանքների ուղիների վրա. այստեղ մշտական ավանի հաստատումը ցույց է տալիս, որ երկու պետությունների միջև ընկած ամայի տափաստանային գոտին սկսել էր հյուսիսից նեղանալ։ Հաջորդ երկու դարերում քաղաքը մնալու էր այս գծի ամենահարավային խոշոր լեհական բնակավայրը։", "7a425b4c"]},
"OLAYLAR_OK106:1638-01-01:0":{"b": ["Մոսկվայի տափաստանային պաշտպանական գծի առաջ մղումը — Չուգուև", "c68d36d3"], "d": ["Լեհաստանում իր ապստամբությունից հետո Մոսկվա ապաստանած կազակ առաջնորդ Յակիվ Օստրյանինը և նրա մարդիկ Դոնեցի ափին հիմնեցին սահմանային բնակավայր։ Սա Ղրիմի արշավանքների դեմ Մոսկվայի ստեղծած պաշտպանական գծի՝ դեպի տափաստան կատարած առաջին մեծ թռիչքներից մեկն էր. հաջորդ կես դարում նույն գծի վրա իրար հետևից ծնվելու էին Սումի, Իզյում և Բախմուտ նման ավանները։ Բնակավայրը մինչև 1765 թվականը գոյատևեց որպես Խարկովի գնդին ենթակա հարյուրյակի կենտրոն։", "3fdefaaa"]},
"OLAYLAR_OK106:1652-01-01:0":{"b": ["Սլոբոդսկայա Ուկրաինայի հիմնադրումը — Սումին և տափաստանային բնակեցման գոտին", "ab7abf59"], "d": ["Աջափնյա Ուկրաինայի Բիլա Ցերկվայի գնդից եկած գյուղացիներն ու կազակները գնդապետ Հերասիմ Կոնդրատիևի առաջնորդությամբ Պսել գետի ափին հիմնեցին նոր ավան. չորս տարի անց Մոսկվայի վոյևոդան ամրացրեց ամրոցը։ Այս գաղթի ալիքը Մոսկվայի հարավային սահմանի ամայի տափաստանը բնակեցման համար բացած Սլոբոդսկայա Ուկրաինայի կարգի սկիզբն է. եկվորներին տրվեց հարկային արտոնություն, իսկ փոխարենը նրանցից սպասվում էր սահմանապահ ծառայություն։ 1658-ից մինչև 1765 թվականը Սումին իր անունը կրող գնդի կենտրոնն էր։", "fc9a8983"]},
"OLAYLAR_OK106:1703-05-17:0":{"b": ["Ենիքալեի կառուցումը — Կերչի նեղուցի փակումը", "d9067015"], "d": ["1700 թ. Ազովը Ռուսաստանին զիջելուց հետո Սև ծովից Ազովի ծով բացվող միակ դուռը վերածվեց ռազմավարական սահմանագծի։ Օսմանյան պետությունը Կերչ քաղաքից տասը կիլոմետր հյուսիս-արևելք՝ Ակընթը Բուռնու կոչվող վայրում, նոր ամրություն կառուցեց և նեղուցի անցումը վերցրեց թնդանոթների հեռահարության տակ. ամրոցին տրվեց հենց Ենիքալե (Նոր բերդ) անունը։ Ամրոցը յոթանասուն տարի մնաց Ղրիմի արևելյան կողպեքը և 1774 թ. Քյուչուկ Կայնարջիի պայմանագրի տասնիններորդ հոդվածով Կերչի հետ միասին զիջվեց Ռուսաստանին։", "8f8533a1"]},
"OLAYLAR_OK106:1754-01-01:0":{"b": ["Սուրբ Ելիզավետայի ամրոցը — Ռուսաստանի հարավային սահմանի հենվելը օսմանա-ղրիմյան արշավանքների գծին", "b9097272"], "d": ["Ռուսաստանը Զապորոժիեի կազակների հողի վրա կառուցեց Սուրբ Ելիզավետա անունը կրող նոր ամրոց։ Ամրոցի բացահայտ հիմնավորումը Նոր Սերբիայում տեղավորված բալկանյան գաղթականներին օսմանյան և ղրիմյան արշավանքներից պաշտպանելն էր, այսինքն՝ ռուսական սահմանագիծը առաջին անգամ իջավ մինչև տափաստանի սիրտը՝ արշավանքների ուղիների վրա։ Այս առաջապահ կետը դարձավ քսան տարի անց Քյուչուկ Կայնարջիով սկսվելիք Հյուսիսային Սևծովյան ընդարձակման մեկնակետը։", "8ac6527e"]},
"OLAYLAR_OK106:1847-05-31:0":{"b": ["Էրզրումի II պայմանագիրը — Շատ ալ-Արաբի սահմանը և Խուզիստանի ափի զիջումը", "5d1f9103"], "d": ["Ավելի քան մեկ դար չլուծված օսմանա-իրանական սահմանային վեճը կարգավորվեց Անգլիայի և Ռուսաստանի միջնորդությամբ տարված երկարատև բանակցություններից հետո Էրզրումում ստորագրված երկրորդ պայմանագրով։ Շատ ալ-Արաբի ջրուղին ամբողջությամբ մնաց Օսմանյան պետությանը, փոխարենը գետի արևելյան ափի բնակավայրերը՝ ներառյալ Մուհամմարա նավահանգիստը և դիմացի Աբադան կղզին, զիջվեցին Ղաջարներին։ Այսպիսով Խուզիստանի ափամերձ շերտը, որը Բասրայի 1546 թ. բռնակցումից ի վեր համարվում էր օսմանյան վարչության ներքո, երեք հարյուր տարի անց դուրս եկավ ձեռքից։ Պայմանագրով գծված սահմանագիծը տեղում ճշտելու համար ստեղծված սահմանային հանձնաժողովի անդամ Մեհմեդ Խուրշիդ փաշան 1848-1852 թվականներին շրջեց տարածաշրջանում և գրեց «Seyâhatnâme-i Hudûd» երկը։", "8fe2f887"]},
"OLAYLAR_OK107:1514-09-15:0":{"b": ["Հեռացումը Թավրիզից — մեկշաբաթյա գրավման ավարտը և վերադարձը Կարս-Բայբուրդ ուղիով", "fd1542e3"], "d": ["Չալդըրանի հաղթանակից հետո սեպտեմբերի 6-ին Թավրիզ մտած սուլթան Յավուզ Սելիմը քաղաքում մնաց մոտ մեկ շաբաթ. նա Շահ Իսմայիլի գանձարանը և քաղաքի արհեստավորների ու գիտնականների մի մասին՝ ընտանիքներով, տեղափոխեց Ստամբուլ։ Թեև նա ցանկանում էր ձմեռն անցկացնել Ղարաբաղում և հաջորդ տարի շարունակել արշավանքը, ենիչերիների ընդդիմության պատճառով հրաժարվեց այդ ծրագրից, և բանակը վերադարձավ Կարսի և Բայբուրդի վրայով։ Այսպիսով Թավրիզը չմնաց օսմանյան ձեռքում. Չալդըրանը դաշտային ճակատամարտի հաղթանակ էր, իսկ տարածքային մշտական ձեռքբերումը եկավ հաջորդ տարի՝ Կամախի, Դիարբեքիրի և Արևելյան Անատոլիայի ռազմագործողությամբ։", "9cc5fc19"]},
"OLAYLAR_OK107:1515-09-19:0":{"b": ["Նուսայբինի, Դերիքի և Սիլոպիի միացումը Օսմանյան պետությանը — Դիարբեքիրի հարավային թևը", "c3621d22"], "d": ["Ամիդի հանձնումից և Դիարբեքիրի բեյլերբեյության հիմնումից հետո, երբ Իդրիս Բիթլիսին իր կողմը գրավեց տարածաշրջանի քուրդ բեյերին, Մարդինի հարթավայրից հարավ ընկած Նուսայբինը, Դերիքը և Սիլոպին նույնպես անցան օսմանյան վարչության տակ։ Այս վայրերը կազմակերպվեցին որպես նոր բեյլերբեյության նահիեի և կազայի կենտրոններ. որոշները, ինչպես Ջիզրեն, յուրթլուք-օջաքլըքի կարգավիճակով թողնվեցին իրենց տեղական բեյերին։ Այսպիսով Չալդըրանից հետո սկսված Արևելյան Անատոլիայի ռազմագործողությունը հասավ Վերին Ջազիրային։", "f975424e"]},
"OLAYLAR_OK109:1918-10-28:0":{"b": ["Չեխոսլովակիայի անկախության հռչակումը — Հաբսբուրգյան ժառանգության առաջին իրավահաջորդ պետությունը", "8f40155f"], "d": ["Պատերազմում Ավստրո-Հունգարիայի ուժի կորստի և երկրի ներսում գործադուլների, ցույցերի ու ապստամբությունների հետևանքով Ազգային խորհուրդը 1918 թ. հոկտեմբերի 28-ին հռչակեց Չեխոսլովակիայի անկախությունը։ 1911 թ. ընտրությունների իրավիճակի հիման վրա ստեղծվեց ժամանակավոր ազգային ժողով, և 1918 թ. նոյեմբերի 14-ին պաշտոնը ստանձնեց կառավարությունը, որի ղեկավարումը հանձնվել էր Մասարիկին։ Նոր պետությունը միջազգային իրավունքում իր տեղը ստացավ Սեն Ժերմեն-ան-Լեի պայմանագրով (1919 թ. սեպտեմբերի 10)։ Քարտեզում Չեխոսլովակիան հայտնվում է 1918 թ. նոյեմբերի 11-ին. անկախության հռչակումը դրանից երկու շաբաթ առաջ է։ Այս հռչակմամբ Հրադեց Կրալովեն (Բոհեմիա), Օլոմոուցը և Բռնոն (Մորավիա) անցան Չեխոսլովակիային։", "74de11eb"]},
"OLAYLAR_OK109:1918-10-29:0":{"b": ["Սլովենների, խորվաթների և սերբերի պետության հռչակումը — Խորվաթիայի Սաբորը խզեց Հաբսբուրգյան կապերը", "2e5ae559"], "d": ["Խորվաթիայի Սաբորը 1918 թ. հոկտեմբերի 29-ին հայտարարեց, որ Խորվաթիան, Սլավոնիան և Դալմաթիան խզել են Ավստրո-Հունգարիայի հետ բոլոր պետաիրավական կապերը. նույն օրը Լյուբլյանայում տոնվեց Սլովենների, խորվաթների և սերբերի պետության հիմնադրումը։ Բոսնիա-Հերցեգովինայում ավստրո-հունգարական վարչությունը 1918 թ. նոյեմբերի 1-ին իշխանությունը հանձնեց Ազգային խորհրդի կառավարությանը։ Այս պետությունը գոյատևեց մինչև 1918 թ. դեկտեմբերի 1-ը, երբ Բելգրադում հռչակվեց Սերբերի, խորվաթների և սլովենների թագավորությունը։", "9e0cf3b3"]},
"OLAYLAR_OK109:1918-10-30:0":{"b": ["Ավստրիայի Հանրապետության հիմնադրումը — Հաբսբուրգյան ժառանգության գերմանական միջուկը", "1ec8b06f"], "d": ["Երբ հոկտեմբերի 29-ին Պրահայում հայտարարվեց Չեխոսլովակիայի, իսկ Զագրեբում՝ Սերբերի, խորվաթների և սլովենների պետության հիմնադրման մասին, Ավստրիայի գերմանացիները նույնպես հոկտեմբերի 30-ին հիմնեցին Ավստրիայի Հանրապետությունը։ Նույն օրը Օսմանյան պետությունը ստորագրում էր Մուդրոսի զինադադարը. երկու կայսրությունների վախճանը օրացույցում հայտնվեց կողք կողքի։", "3772c9f7"]},
"OLAYLAR_OK109:1918-10-31:0":{"b": ["Աստղածաղիկների հեղափոխություն — Կարոյին դարձավ վարչապետ, Հունգարիայում սկսեց քայքայվել միապետությունը (ժողովրդական հանրապետությունը հռչակվեց նոյեմբերի 16-ին)", "d7780d2e"], "d": ["Երբ պարզ դարձավ Կենտրոնական տերությունների պարտությունը, Հունգարիայում ուժեղացան հակամիապետական տրամադրությունները և տեղի ունեցավ թեքում դեպի ձախ։ 1918 թ. հոկտեմբերի 31-ին «աստղածաղիկների հեղափոխության» ավարտին արմատական հայացքների տեր կոմս Միհայ Կարոյին դարձավ վարչապետ, այնուհետև հռչակվեց ժողովրդական հանրապետություն. Կարոյին 1919 թ. հունվարի 11-ին ընտրվեց մշտական նախագահ։", "0a48f4b7"]},
"OLAYLAR_OK109:1918-11-03:0":{"b": ["Վիլլա Ջուստիի զինադադարը — Ավստրո-Հունգարիան վայր դրեց զենքը, Տրենտոն և Տրիեստը անցան Իտալիային", "75da65fb"], "d": ["Կայսր Կառլի կողմից 1918 թ. նոյեմբերի 3-ին իտալացիների հետ Վիլլա Ջուստիում զինադադարի ստորագրումը արագացրեց կայսրության մասնատումը։ TDV-ն այս օրը բացահայտորեն արձանագրում է որպես Ավստրիայի զենքը վայր դնելու օր. «Պարտությունն ընդունած Ավստրիան նոյեմբերի 3-ին, իսկ Գերմանիան նոյեմբերի 11-ին վայր դրեցին զենքերը»։ Քարտեզում Տրենտոն և Տրիեստը այս օրը Ավստրիայից անցնում են Իտալիային. սա փլուզման՝ քարտեզում երևացող առաջին տարածքային փոխանցումն է։ Այս զինադադարով Բրեններ–Տոբլախ–Հուլյան Ալպեր գծից հարավ գտնվող Բրիքսենը, Կորտինա դ'Ամպեցցոն, Գյորցը և Գրադիսկան անցան իտալական գրավման տակ։", "11a74dbf"]},
"OLAYLAR_OK109:1918-11-11:0":{"b": ["Լեհաստանի անկախությունը — Խնամակալական խորհուրդը բանակի հրամանատարությունը հանձնեց Պիլսուդսկուն", "e8b546cf"], "d": ["Յուզեֆ Պիլսուդսկին 1918 թ. նոյեմբերի 10-ին վերադարձավ Վարշավա։ Նոյեմբերի 11-ին Խնամակալական խորհուրդը բանակի հրամանատարությունը հանձնեց նրան, իսկ մի քանի օր անց նրան հանձնեց նաև ազգային կառավարություն կազմելու պարտականությունը։", "578314ea"]},
"OLAYLAR_OK109:1918-11-14:0":{"b": ["Սերբական բանակը գրավեց Պեչը — սկսվեց Բարանյայի սերբական օկուպացիան", "68f0695f"], "d": ["Ածխահանքերի պատճառով ռազմավարական նշանակություն ունեցող Պեչը 1918 թ. նոյեմբերի 14-ին անցավ սերբական օկուպացիայի տակ։ Պեչի և Բարանյա նահանգի սերբական օկուպացիան տևեց մինչև 1921 թ. օգոստոսը։", "7222b6bd"]},
"OLAYLAR_OK109:1918-11-14:1":{"b": ["Սերբական բանակը գրավեց Տիմիշոարան — սկսվեց Բանատի սերբական ռազմական վարչությունը", "3cc85350"], "d": ["1918 թ. նոյեմբերի 14-ին սերբական զորամասերը գրավեցին Տիմիշոարան, ցրեցին ազգային գվարդիան և ստանձնեցին Բանատի ռազմական, իսկ կարճ ժամանակ անց նաև քաղաքացիական վարչությունը։ Դեկտեմբերի սկզբին քաղաք մտան նաև ֆրանսիական զորամասեր. ռումինական վարչությունը հաստատվեց միայն 1919 թ. հուլիս-օգոստոսին։", "78697a6b"]},
"OLAYLAR_OK109:1918-11-19:0":{"b": ["Սերբական զորամասերը մտան Սիգետվար — Հարավային Շոմոդի գրավումը", "a06b1907"], "d": ["Բելգրադի ռազմական համաձայնագրով գծված գծից հյուսիս առաջացող սերբական բանակից Օբրեն Պետրովիչի հրամանատարությամբ 220 զինվոր 18-ից 19-ի գիշերը մտան Շոմոդի գավառի կենտրոն Սիգետվար. այդ ուժով պահվեցին նաև գավառի գյուղերը։ Գրավումը տևեց մինչև 1921 թ. օգոստոսը. Տրիանոնի պայմանագիրը Սիգետվարը թողեց Հունգարիային։", "9485d5ab"]},
"OLAYLAR_OK109:1918-12-01:0":{"b": ["Սերբերի, խորվաթների և սլովենների թագավորության և Մեծ Ռումինիայի հիմնադրումը — նույն օրը, երկու պետություն", "6fd85345"], "d": ["Ավստրո-Հունգարիայի փլուզմամբ կայսրությունից անջատված սլավոնների՝ Սերբիայի հետ միավորման արդյունքում 1918 թ. դեկտեմբերի 1-ին հիմնվեց Սերբերի, խորվաթների և սլովենների թագավորությունը. մոտ 250.000 կմ² տարածք և 12.000.000 բնակչություն։ Հիմքը դրվել էր 1917 թ. հուլիսի 20-ի Կորֆուի հռչակագրում. հոկտեմբերի 26-ին Պոդգորիցայի, հոկտեմբերի 28-ին Բոսնիա-Հերցեգովինայի, նոյեմբերի 25-ին Նովի Սադի ժողովները որոշել էին միանալ։ Նույն օրը Տրանսիլվանիայի, Բուկովինայի և Բեսարաբիայի՝ իրենց ժողովուրդների որոշմամբ միանալով ձևավորվեց Մեծ Ռումինիան։ Քարտեզում Սերբիայի թագավորության տարածքները անցնում են Հարավսլավիային։ Թագավորության հիմնադրմամբ Սերբիայի թագավորության բոլոր տարածքները (Նիշ, Սկոպյե, Բիտոլա, Օհրիդ, Պրիշտինա, Պրիզրեն, Պեչ և այլն) անցան Սերբերի, խորվաթների և սլովենների թագավորությանը։", "4fd0ff67"]},
"OLAYLAR_OK109:1918-12-01:1":{"b": ["Ռումինական բանակը մտավ Բրաշով և դիմավորվեց հանդիսավոր արարողությամբ", "4a917d27"], "d": ["Ռումինական բանակը 1918 թ. դեկտեմբերին մտավ Բրաշով. քաղաքի ռումին երևելիները բանակը և գեներալ Բերթելոյին դիմավորեցին հանդիսավոր արարողությամբ։", "96d03f2f"]},
"OLAYLAR_OK109:1918-12-19:0":{"b": ["Իտալական բանակը գրավեց Կնինը", "7949dd0f"], "d": ["Իտալական բանակը 1918 թ. դեկտեմբերի 19-ին գրավեց Կնինը։ Օկուպացիան տևեց մինչև 1921 թ. ապրիլի 4-ը, երբ Ռապալլոյի պայմանագրից հետո իտալական բանակը հեռացավ քաղաքից։", "f4363313"]},
"OLAYLAR_OK109:1918-12-29:0":{"b": ["Չեխոսլովակյան զորամասերը վերցրին Կոշիցեն", "0989490f"], "d": ["Երբ Ալոիս Յիրասեկի անունը կրող 30-րդ հետևակային գունդը 1918 թ. դեկտեմբերի 29-ին գրավեց քաղաքը, Կոշիցեն փաստացի միացավ Չեխոսլովակիայի Հանրապետությանը։", "2453b355"]},
"OLAYLAR_OK109:1919-04-20:0":{"b": ["Ռումինական բանակը մտավ Սատմար (ապրիլի 19) և Օրադեա (Վարադ, ապրիլի 20)", "3ee2bd72"], "d": ["1919 թ. ապրիլի 19-ին՝ Զատկի շաբաթ օրը, Սատու Մարեում դոկտ. Իլիե Կարոլ Բարբուլի ղեկավարած տեղական պատվիրակությունը Սոմեշի կամրջի վրա դիմավորեց գնդապետ Ռեսելի հրամանատարությամբ 2-րդ հեծելազորային դիվիզիայի առաջին պարեկախումբը։ Հաջորդ օրը՝ 1919 թ. ապրիլի 20-ին, գեներալ Տրայան Մոշոյուի հրամանատարությամբ ռումինական զորամասերը մտան Օրադեա։", "9249e364"]},
"OLAYLAR_OK109:1919-06-28:0":{"b": ["Վերսալի պայմանագիրը — Էլզաս-Լոթարինգիայի վերադարձը Ֆրանսիային իրավական ուժ ստացավ", "3babdfcb"], "d": ["Փարիզի խաղաղության կոնֆերանսը հավաքվեց 1919 թ. հունվարի 18-ին, և հունիսի 28-ին Գերմանիայի հետ ստորագրվեց Վերսալի պայմանագիրը։ Պայմանագրի 51-րդ հոդվածը 1871 թվականից գերմանական Էլզաս-Լոթարինգիան (Ստրասբուրգ, Մեց, Կոլմար, Մյուլուզ) վերադարձրեց Ֆրանսիայի ինքնիշխանությանը, սակայն փոխանցումը կապեց ոչ թե ստորագրման օրվա, այլ հետադարձ ուժով՝ 1918 թ. նոյեմբերի 11-ի զինադադարի հետ։ Նույն կոնֆերանսների շարքը ծնեց Ավստրիայի հետ Սեն Ժերմենի (1919 թ. սեպտեմբերի 10), Բուլղարիայի հետ Նեյիի (1919 թ. նոյեմբերի 27), Հունգարիայի հետ Տրիանոնի (1920 թ. հունիսի 4) և Օսմանյան պետության հետ Սևրի (1920 թ. օգոստոսի 10) պայմանագրերը։", "4ab970de"]},
"OLAYLAR_OK109:1919-07-22:0":{"b": ["Ռումինական զորամասերը հասան Լուգոժ — ռումինական վարչություն Բանատի արևելքում", "f65fc73c"], "d": ["Ռումինական զորամասերը տեղափոխող գնացքը 1919 թ. հուլիսի 22-ին ժամը 14-ին հասավ Լուգոժ. քաղաքի բնակիչները բանակը դիմավորեցին կայարանում, Կարաշ-Սևերինի պրեֆեկտ Ջորջ Դոբրինը ողջույնի խոսք արտասանեց, իսկ գեներալ Ժիտիանուն պատասխանեց։ Բանատի՝ Ռումինիային բաժին ընկած մասում ռումինական վարչությունը հաստատվեց 1919 թ. հուլիսին. իրավական փոխանցումը կատարվեց 1920 թ. Տրիանոնի պայմանագրով։", "b228ed28"]},
"OLAYLAR_OK109:1919-08-03:0":{"b": ["Ռումինական բանակը մտավ Տիմիշոարա — քաղաքում հաստատվեց ռումինական վարչություն", "8728e1d1"], "d": ["Տիմիշոարա, ուր 1918 թ. նոյեմբերի 14-ին մտել էին սերբական, իսկ դեկտեմբերի սկզբին՝ ֆրանսիական զորամասերը, 1919 թ. օգոստոսի 3-ի առավոտյան մտան գնդապետ Վիրջիլ Էկոնոմուի հրամանատարությամբ ռումինական բանակի առաջին զորամասերը, և քաղաքում հաստատվեց ռումինական վարչություն։", "0b1627d3"]},
"OLAYLAR_OK109:1919-08-12:0":{"b": ["ՍԽՍ բանակը մտավ Պրեկմուրյե — Մուրսկա Սոբոտան և Լենդավան դուրս եկան հունգարական վարչությունից", "21b2ba08"], "d": ["Սերբերի, խորվաթների և սլովենների թագավորության զորամասերը 1919 թ. օգոստոսի 12-ին մտան Մուրա գետից այն կողմ գտնվող Պրեկմուրյե. տարածաշրջանում հունգարական վարչությունը այդ օրը դադարեց։ Իրավական փոխանցումը կատարվեց 1920 թ. Տրիանոնի պայմանագրով։", "3ce8a913"]},
"OLAYLAR_OK109:1919-09-10:0":{"b": ["Սեն Ժերմենի պայմանագիրը — Ավստրիայի փոքրացումը իրավական ուժ ստացավ", "e7b722d5"], "d": ["Պատերազմից հետո Ավստրիան դաշնակիցների հետ ստորագրեց Սեն Ժերմենի հաշտության պայմանագիրը։ Պայմանագրի համաձայն Ավստրիան ճանաչում էր Հունգարիայի, Չեխոսլովակիայի և Հարավսլավիայի անկախությունը, ընդունում էր առանց Ազգերի լիգայի համաձայնության չմիավորվել Գերմանիայի հետ, վերացնել պարտադիր զինծառայությունը և սահմանափակել բանակը 30.000 մարդով։ Սա նաև այն փաստաթուղթն է, որով Չեխոսլովակիան ձեռք բերեց իր տեղը միջազգային իրավունքում։ Քարտեզում փոխանցումը տեղի էր ունեցել մեկ տարի առաջ. այս պայմանագիրը այն վավերացրեց։ Այս պայմանագրով Լվովը, Յազլովեցը, Կարվինան և Դալմաթիայի ափն ու կղզիները (Կրկ, Ցրես, Լոշին, Ռաբ, Պագ, Հվար, Կորչուլա, Վիս, Զադար, Շիբենիկ, Կնին) Ավստրիայից անցան Գլխավոր դաշնակից տերությունների տնօրինությանը, իսկ Ունգվարը և Մունկաչը (Կարպատյան Ռութենիա)՝ Չեխոսլովակիային։", "b4d5f306"]},
"OLAYLAR_OK109:1919-11-27:0":{"b": ["Նեյիի պայմանագիրը — Բուլղարիան կորցրեց Արևմտյան Թրակիան և Էգեյան ծովի ափը", "01f2b8c8"], "d": ["Պատերազմի պարտությամբ ավարտվելու հետևանքով ցար Ֆերդինանդը ստիպված էր եղել զինադադար խնդրել և գահից հրաժարվել հօգուտ որդու՝ Բորիսի (1918 թ. սեպտեմբերի 29)։ Պատերազմը ավարտող Նեյիի պայմանագրով Բուլղարիան ռազմավարական տարածքային կորուստներ կրեց հօգուտ սերբերի, կորցրեց ամբողջ Արևմտյան Թրակիան, ստիպված եղավ Էգեյան ծովի ափը զիջել Հունաստանին և հաստատեց Բուխարեստի պայմանագրի այն դրույթները, որոնք Հարավային Դոբրուջան տալիս էին Ռումինիային։ Քարտեզում այս փոխանցմանը համապատասխան փոփոխությունը ոչ թե պայմանագրի օրն է, այլ 1920 թ. մայիսին, երբ վարչությունը փաստացի փոխվեց. Ալեքսանդրուպոլիսը, Սոֆլուն, Օրեստիադան և Չիրմենը մայիսի 14-ին, իսկ Կոմոտինին, Քսանթին, Դիդիմոտիխոն և Ֆերեջիկը մայիսի 27-ին անցնում են Հունաստանին։", "d61eb549"]},
"OLAYLAR_OK109:1920-06-04:0":{"b": ["Տրիանոնի պայմանագիրը — Հունգարիան կորցրեց իր տարածքի երկու երրորդը", "84aff507"], "d": ["1920 թ. մարտի 1-ին Հորթիին թագավորական խնամակալի պաշտոնում նշանակելուց երեք ամիս անց ստորագրված Տրիանոնի պայմանագրի համաձայն Հունգարիան ծանր տարածքային և մարդկային կորուստներ կրեց. Խորվաթիան չհաշված՝ նրա 283.000 կմ² տարածքի երկու երրորդը և բնակչության վաթսուն տոկոսը, այդ թվում՝ ավելի քան երեք միլիոն հունգարացի, մնացին սահմանից դուրս, իսկ բանակը կրճատվեց մինչև 35.000 մարդ։ Քարտեզում Հունգարիայի խնամակալությունը երևում է այս փոքրացված սահմաններով. Տրանսիլվանիան և Վերին Հունգարիան հենց այս օրը անցնում են Ռումինիայի և Չեխոսլովակիայի գույնին։ Այս պայմանագրով Բրատիսլավան, Կաշշան, Նիտրան և Կոմարոմը (Վերին Հունգարիա) իրավաբանորեն անցան Չեխոսլովակիային, Վարադը, Սատմարը, Լուգոշը, Ալբա Յուլիան և Բրաշովը (Տրանսիլվանիա և Բանատի արևելքը)՝ Ռումինիային, Սուբոտիցան, Բեչկերեկը, Բաչը, Մուրսկա Սոբոտան և Չակովեցը (Բաչկա, Բանատի արևմուտքը, Պրեկմուրյե, Մեջիմուրյե)՝ Սերբերի, խորվաթների և սլովենների թագավորությանը։", "f7c54f07"]},
"OLAYLAR_OK109:1920-06-04:1":{"b": ["Բանատը բաժանվեց, Տիմիշոարան թողնվեց Ռումինիային (Տրիանոն, հոդ. 27/3 և 45)", "256b4aca"], "d": ["Տրիանոնի պայմանագիրը 27/3 հոդվածով գծեց հունգարա-ռումինական սահմանը, իսկ 45-րդ հոդվածով Հունգարիան այդ սահմանից այն կողմ գտնվող նախկին միապետության հողերի նկատմամբ իր բոլոր իրավունքներից և տիտղոսներից հրաժարվեց հօգուտ Ռումինիայի. այսպիսով Տրանսիլվանիայի, Բանատի, Կրիշանայի և Մարամուրեշի միավորումը Ռումինիայի հետ ճանաչվեց միջազգային իրավունքում։ Բանատի շրջանը բաժանվեց Ռումինիայի և Սերբիայի միջև. Տիմիշոարա քաղաքը միացավ Ռումինիայի թագավորությանը։ Տիմիշոարայում ռումինական վարչությունը փաստացի գործում էր 1919 թ. օգոստոսի 3-ից. պայմանագիրը այդ իրավիճակը իրավական դարձրեց։", "5ec9c446"]},
"OLAYLAR_OK109:1921-04-04:0":{"b": ["Իտալական բանակը հեռացավ Կնինից", "a1d2e846"], "d": ["Ռապալլոյի պայմանագրից հետո իտալական բանակը 1921 թ. ապրիլի 4-ին հեռացավ Կնինից. ավարտվեց 1918 թ. դեկտեմբերի 19-ին սկսված օկուպացիան։", "0af4a592"]},
"OLAYLAR_OK109:1921-06-12:0":{"b": ["Իտալիան Շիբենիկը հանձնեց ՍԽՍ թագավորությանը", "9d07b12a"], "d": ["1918 թ. նոյեմբերի 6-ին սկսված իտալական օկուպացիան ավարտվեց 1921 թ. հունիսի 12-ին՝ Իտալիայի և ՍԽՍ թագավորության ռազմական ներկայացուցիչների մասնակցությամբ արարողությամբ։", "3d4d272c"]},
"OLAYLAR_OK109:1921-08-20:0":{"b": ["Սերբական զորամասերը հեռացան Սիգետվարից — հունգարական ժանդարմերիան ստանձնեց քաղաքը", "97781b77"], "d": ["Տրիանոնի պայմանագրի ուժի մեջ մտնելուց հետո սերբական ուժերը օգոստոսի 17-ին սկսեցին հեռանալ Բարչից և Սիգետվարից՝ իրենց հետ տանելով այն ամենը, ինչ հնարավոր էր տանել։ Օգոստոսի 20-ին՝ կեսօրի մոտ, մտան հունգարական ժանդարմերիայի ջոկատները. կեսօրից հետո քաղաքապետական խորհուրդը և պաշտոնյաները երդում տվեցին, իսկ ժամը հինգին քաղաքապետարանի շենքում կատարվեց ռազմական ընդունման-հանձնման արարողությունը։", "1db599da"]},
"OLAYLAR_OK109:1921-08-22:0":{"b": ["Ավարտվեց Պեչի սերբական օկուպացիան — Հունգարական ազգային բանակը մտավ քաղաք", "f437115a"], "d": ["Սերբական զորամասերը 1921 թ. օգոստոսի 18-ին սկսեցին ազատել տարածաշրջանը. օգոստոսի 20-21-ին քաղաքի և նահանգի վարչությունը փոխանցվեց Հունգարիայի կառավարության ներկայացուցիչներին, իսկ օգոստոսի 22-ին Հունգարական ազգային բանակի զորամասերը մտան քաղաք։", "0210d518"]},
"OLAYLAR_OK109:1921-11-13:0":{"b": ["Ավստրիայի Բունդեսհեերը մտավ Բուրգենլանդ — Տրիանոնով Ավստրիային թողնված հողը փաստացի ստանձնվեց", "7bfd6915"], "d": ["Տրիանոնի (1920) և Սեն Ժերմենի (1919) պայմանագրերը Արևմտյան Հունգարիայի գերմանախոս շերտը թողել էին Ավստրիային. 1921 թ. օգոստոսի 28-ի առաջին ստանձնման փորձը ձախողվեց հունգարական անկանոն ջոկատների դիմադրության պատճառով։ Վենետիկի արձանագրությունից (1921 թ. հոկտեմբերի 13) հետո Դաշնակիցների գլխավոր հանձնաժողովը նոյեմբերի 11-ին հաստատեց Բունդեսհեերի մուտքը, և երկու օր անց սկսվեց հյուսիսային Բուրգենլանդի ստանձնումը. հարավը ստանձնվեց 1921 թ. դեկտեմբերի 6-ին, իսկ Շոպրոնի շրջանը հանրաքվեով մնաց Հունգարիային։", "c78d0f81"]},
"OLAYLAR_P0043A:1456-01-01:0":{"b": ["Պիրոտը վերադարձավ օսմանյան տիրապետության տակ. Գեորգ Բրանկովիչի մահը", "e37156d1"], "d": ["1443 թվականին խաչակրաց բանակի գրաված և 1444 թվականի Էդիրնե-Սեգեդի պայմանագրից հետո Մուրադ II-ի կողմից սերբերին թողնված Պիրոտը 1456 թվականին, սերբ դեսպոտ Գեորգ Բրանկովիչի մահով, վերադարձավ օսմանյան տիրապետության տակ։ Նույն տարում և նույն պատճառով Նիշը ևս վերջնականապես անցավ օսմանյան կառավարման տակ. այսպիսով ամբողջացավ Նիշավայի հովտի՝ դեպի Սոֆիայի ճանապարհ բացվող գիծը։ Պայմանագիրը ստորագրվել էր տասը տարի ժամկետով, և Վառնայից (1444) ու Կոսովոյի երկրորդ ճակատամարտից (1448) հետո դեսպոտության կյանքը տևեց միայն այնքան, որքան Բրանկովիչի կյանքը։", "4b6ec617"]},
"OLAYLAR_P0043B:1514-03-20:0":{"b": ["Յավուզ Սուլթան Սելիմը Չալդըրանի արշավանքի համար ճանապարհ ընկավ Էդիրնեից", "1f7921f7"], "d": ["Մանիսայում գտնվող իր որդի շահզադե Սուլեյմանին Ստամբուլում որպես փոխանորդ թողնելով՝ Յավուզ Սուլթան Սելիմը Սեֆյան պետության դեմ ձեռնարկած իր արշավանքի համար ճանապարհ ընկավ Էդիրնեից։ Բանակը Անատոլիան անցնելու էր Սեբաստիա-Երզնկա-Էրզրում գծով և օգոստոսի վերջին Չալդըրանում հանդիպելու էր Շահ Իսմայիլի ուժերին։", "430f5ccc"]},
"OLAYLAR_P0043KIRIM:1526-01-01:0":{"b": ["Կիզիքերմենի (Ղազի Քերման) և Դնեպրի աջ ափի անցումը Օսմանյան պետության ուղղակի վերահսկողության տակ", "56a28224"], "d": ["Ղրիմի խանության՝ 15-րդ դարի կեսից տիրապետած Կիզիքերմեն ամրոցը և Դնեպրի աջ ափն այս թվականին անցան Օսմանյան պետության ուղղակի վերահսկողության տակ. ամրոցը վերածվեց տափաստանի հյուսիսային ծայրի օսմանյան առաջապահ դիրքի։ Ի տարբերություն Բախչիսարայի և Օր Կապիի շրջակայքի՝ Ղրիմի խանության հողերի, Կիզիքերմենի կառավարումը անմիջականորեն Օսմանյան պետության ձեռքին էր։", "a0eaba40"]},
"OLAYLAR_P0043KIRIM:1776-12-03:0":{"b": ["Պրոզորովսկին գրավեց Օր Կապին. ռուսական ուժերը մինչև բռնակցումը մնացին Օրկապիում", "afdfe804"], "d": ["Երբ Շահին Գիրեյին Ղրիմի գահ բարձրացնելու համար արշավող գեներալ Պրոզորովսկին հասավ Պերեկոպի գիծ, Դևլեթ Գիրեյը, կայմակամը և թաթարները արդեն դուրս էին եկել քաղաքից. Պրոզորովսկին առանց կռվի գրավեց Օր ամրոցը և Պերեկոպի գիծը։ Ռուսները հաստատվեցին Օր Կապիում և մնացին այնտեղ մինչև 1783 թվականի Ղրիմի բռնակցումը։", "2c53b49b"]},
"OLAYLAR_P0043KIRIM:1791-07-26:0":{"b": ["Անապայի գրավումը ռուսների կողմից (երրորդ պաշարում)", "e6a7d6d5"], "d": ["1781 թվականին Ֆերահ Ալի փաշայի կառավարման օրոք կառուցված Անապա ամրոցը պատերազմի ընթացքում ռուսները երեք անգամ պաշարեցին. երրորդ պաշարման վերջում՝ 1791 թվականի հուլիսի 26-ին, այն գրավվեց։ Գրավումը ժամանակավոր էր. քանի որ Յասիի պայմանագրով (1792) Կովկասում ընդունվեցին հին սահմանները, ամրոցը վերադարձվեց Օսմանյան պետությանը։", "6f3b16fa"]},
"OLAYLAR_P0043KIRIM:1828-06-24:0":{"b": ["Անապայի հանձնումը ռուսներին Օսման փաշայի կողմից", "3ccbdd1d"], "d": ["1828-29 թվականների ռուս-թուրքական պատերազմի սկզբնական փուլում Անապան պաշարվեց, և ամրոցում գտնվող օսմանյան ուժերը Օսման փաշայի հրամանատարությամբ 1828 թվականի հունիսի 24-ին անձնատուր եղան ռուսներին։ Այս անգամ հանձնումը վերջնական էր. հաջորդ տարի ստորագրված Ադրիանապոլսի պայմանագրով (1829 թ. սեպտեմբերի 14) Անապան և Կովկասը պաշտոնապես դուրս եկան օսմանյան տիրապետությունից։", "d49b4078"]},
"OLAYLAR_P0044:1556-01-01:0":{"b": ["Թուրգութ ռեիսը դարձավ Տրիպոլիտանիայի բեյլերբեյ. էյալեթը արևելքում ընդլայնվեց մինչև Տոբրուկ և Դերնա", "160fa43c"], "d": ["1551 թվականին Տրիպոլիի նվաճումից հետո Թուրգութ ռեիսը հիջ. 963 թվականի Ջումադա ալ-ուլա ամսին (1556 թ. մարտ) բեյլերբեյի տիտղոսով եկավ Տրիպոլի։ Իր ինը տարի տևած կուսակալության ընթացքում նա աշխատեց էյալեթի բարեկարգման և ամրացման համար, օսմանյան կառավարումը հարավում հասցրեց մինչև Ֆեցան և, սահմաններն ընդլայնելով դեպի արևելք, գրավեց Բարքայի ափին գտնվող Տոբրուկն ու Դերնան։ Այսպիսով Տրիպոլիի էյալեթը սկսեց ընդգրկել մինչև Եգիպտոսի սահմանը ձգվող ափամերձ շերտը։", "44cf4583"]},
"OLAYLAR_P0044:1556-01-01:1":{"b": ["Մոսկովյան թագավորությունը գրավեց Աստրախանը. Ստորին Վոլգան անցավ ռուսական վերահսկողության տակ", "d02abd83"], "d": ["Մոսկովյան թագավորությունը 1556 թվականին գրավելով նաև Աստրախանը՝ TDV-ի ձևակերպմամբ կատարեց «ապագայի համար շատ կարևոր հետևանքներ ունեցող քայլ». Աստրախանի խանության գրավմամբ Ստորին Վոլգան անցավ ռուսական վերահսկողության տակ։ Ղրիմի խան Դևլեթ Գիրեյը, թեև ցանկացավ կանխել այս գրավումները, չհաջողեց։ Օսմանցիներն այս զարգացմանը 1569 թվականին պատասխանեցին Աստրախանի արշավանքով. սակայն, Ստորին Վոլգայի շրջանի վերահսկողության հարցում հաջողության չհասնելով, Մոսկովյան թագավորության դեմ պայքարը թողեցին Ղրիմի խանին։", "7e08ba29"]},
"OLAYLAR_P0044:1556-07-16:0":{"b": ["Կոստայնիցայի և Նովիի նվաճումը՝ Ունայի գծի երկու ամրոցները", "2093e452"], "d": ["1556 թվականի ամռանը Մալկոչ բեյի պաշարած Կոստայնիցան ավելի քան 60 զինվորով պաշտպանում էր կապիտան Պանկրացիե Լուստհալերը. ամրոցը հանձնվեց պաշարումը սկսվելուց ընդամենը մեկ օր անց՝ հուլիսի 16-ին, և Լուստհալերը մեղադրվեց ամրոցը վաճառելու մեջ։ Կարճ ժամանակ անց գրավվեց և այրվեց նաև Նովին. այսպիսով Ունայի վրա գտնվող երկու կարևորագույն ամրոցները մեկ հարվածով անցան օսմանյան ձեռքը։ Նույն տարում Վիեննայում ստեղծվեց Արքունի ռազմական խորհուրդը (Hofkriegsrat), որը կենտրոնից էր ղեկավարելու սահմանային պաշտպանությունը։", "b985cbdf"]},
"OLAYLAR_P0044:1574-01-01:0":{"b": ["Մակուն անցավ Օսմանյան պետությանը. Մահմուդի Իվազ բեյին ամրոց կառուցելու հանձնարարություն", "5932ad38"], "d": ["1574 թվականին Օսմանյան պետությունը Մահմուդի քրդական ցեղի առաջնորդ Իվազ բեյին հանձնարարեց Մակուն խլել իրանցիներից և այնտեղ ամրոց կառուցել։ Վանի էյալեթի արևելյան ծայրի այս ամրոցը օսմանյան շրջանում կարևոր տեղ ունեցավ տարածաշրջանում տեղի ունեցած իրադարձություններում։", "bd663d7c"]},
"OLAYLAR_P0044:1840-01-01:0":{"b": ["Թողարկվեց առաջին օսմանյան թղթադրամը (կայմե)", "d2e5e192"], "d": ["Թանզիմաթի առաջին տարիներին գանձարանի համար եկամուտ որոնելու ընթացքում, հետագայում շեյխուլիսլամ դարձած Արիֆ Հիքմեթ բեյի առաջարկով, ընդունվեց կայմեի կիրառումը՝ էսհամ համակարգի զարգացած ձևը։ Ընդհանուր 160 000 լիրա (32 000 քսակ) արժողությամբ առաջին կայմեները, դրամի հրատապ կարիքի պատճառով տպագրվելուն չսպասելով, ձեռագիր թողարկվեցին ֆինանսների նախարար Սաիբ փաշայի օրոք, հավանաբար 1840 թվականի հունիսին։ Կանխիկ դրամի ուժ ունեցող այս թղթերի շրջանառության ժամկետը ութ տարի էր, տոկոսը՝ տարեկան 12,5 %. դրանք ծածկույթ չունեին, միայն տոկոսների համար որպես ապահովություն ցույց էր տրվել Ստամբուլի մաքսատան եկամուտը։ Ժողովուրդը բարեհաճ չընդունեց իրեն անսովոր այս դրամը, և ձեռագիր կայմեները կարճ ժամանակում դարձան կեղծարարների թիրախ։", "1f5f905c"]},
"OLAYLAR_P0047:1511-08-10:0":{"b": ["Մալակկայի գրավումը պորտուգալացիների կողմից", "e1556746"], "d": ["1390-ական թվականներին հիմնված Մալակկան, լինելով Չինաստանի, Հնդկաստանի և Արևմուտքի միջև ծովային առևտրի՝ շրջանի ամենաբանուկ նավահանգիստն ու Մալակկայի սուլթանության կենտրոնը, դարձել էր նաև իսլամի շրջակա կղզիներ տարածվելու գլխավոր օջախը։ Պորտուգալացի Աֆոնսո դե Ալբուկերկեն 1511 թվականի օգոստոսի 10-ին գրավեց քաղաքը. քաղաքը թալանվեց, նրա մզկիթները, արքայական դամբարանները և քարաշեն մյուս շինությունները ավերվեցին, որպեսզի քարերն օգտագործվեն ամրոց կառուցելու համար։ Պորտուգալական կառավարման տակ Մալակկան չկարողացավ պահպանել իր նախկին առևտրային գերակայությունը. մահմեդական վաճառականները ուղղվեցին Սումատրայի Աչեի սուլթանության նավահանգիստ։ Մալայայում հաստատված պորտուգալացիների՝ Աչեի վրա հարձակումների կապակցությամբ Աչեի սուլթան Ալաեդդին Ռիայաթ շահը 1565 թվականին Կանունի Սուլթան Սուլեյմանից օգնություն խնդրեց։", "bfb60150"]},
"OLAYLAR_P0048:1592-01-01:0":{"b": ["Լուրիստանի տիրակալ Շահվերդին հավատարմություն հայտնեց Շահ Աբբասին", "85791f94"], "d": ["1589 թվականին օսմանցիներին հպատակվելով Բաղդադի բեյլերբեյի վասալը դարձած Լուրիստանի տիրակալ Շահվերդին, ըստ Սեֆյան պատմիչ Իսկանդար բեյ Մունշիի պատմածի, 1000 (1591-92) թվականին ստիպված եղավ հավատարմություն հայտնել Սեֆյան թագին։ Նույն աղբյուրը գրում է, որ այդ տարիներին նա տատանվում էր երկու կողմերի միջև, անհանգստացնում էր Համադանի կուսակալներին և արշավանքներ էր կատարում Բորուջերդի վրա, և որ 1002 (1593-94) թվականին Շահ Աբբասը գրավեց Խորրամաբադը և քաղաքում կուսակալ նշանակեց։ Իսկ TDV իսլամական հանրագիտարանը 1590 թվականի Կոստանդնուպոլսի պայմանագրով օսմանյան կառավարմանը կապված Լուրիստանի լիովին Սեֆյաններին կապվելը դնում է 1603 թվականին։ Երկու ավանդույթը տարբեր թվական են տալիս. այս հոդվածը ցույց է տալիս Սեֆյան ավանդույթի հավատարմության հայտարարությունը, իսկ 1603 թվականի հոդվածը՝ վերջնական կորուստը։ Քարտեզում այս հոդվածով տիրոջ փոփոխություն չկա. Լուրիստանը մինչև 1603 թվականը երևում է օսմանյան կողմում։", "d15b2c77"]},
"OLAYLAR_P0048:1603-01-01:0":{"b": ["Լուրիստանի վերջնական անցումը Սեֆյաններին", "4c5cf67b"], "d": ["1590 թվականի Կոստանդնուպոլսի (Ֆերհադ փաշայի) պայմանագրով օսմանյան կառավարմանը կապված Լուրիստանը Շահ Աբբաս I-ը 1603 թվականին լիովին կապեց Սեֆյաններին։ Սեֆյան պատմիչ Իսկանդար բեյ Մունշին, սակայն, գրում է, որ Խորրամաբադը Շահ Աբբասն ավելի վաղ՝ 1002 (1593-94) թվականին, գրավել և քաղաքում Սեֆյան կուսակալ էր նշանակել. երկու ավանդույթի այս տարբերությունը լուծված չէ։ Նույն տարում Լուրիստանից հյուսիս գտնվող օսմանյան Նեհավենդ ամրոցն էլ անցավ Շահ Աբբասի ձեռքը. Համադանի կուսակալ Հասան խանը ամրոցը հավասարեցրեց հողին։", "3e110da7"]},
"OLAYLAR_P0049:1303-09-01:0":{"b": ["Կատալոնական ընկերությունը մտավ Բյուզանդիայի ծառայության. Անատոլիական արշավանքի սկիզբը", "6623e7db"], "d": ["Արևմտյան Անատոլիայում թուրքական բեյությունների առաջ հողեր կորցնող Բյուզանդական կայսրությունը որպես վարձու զորք իր ծառայության վերցրեց Ռոժե դե Ֆլորի հրամանատարությամբ մոտ 6500 հոգանոց կատալոնական ջոկատը։ TDV-ի Բյուզանդիային նվիրված հոդվածի համաձայն՝ ջոկատը 1303 թվականին եկավ կայսրությանն օգնության և հաջորդ տարի փրկեց Գերմիյանյանների պաշարած Ալաշեհիրը։ Սակայն ընկերությունը կարճ ժամանակում սկսեց թալանել իր անցած վայրերը. Բյուզանդիան այն անցկացրեց Թրակիա և 1305 թվականին սպանել տվեց Ռոժե դե Ֆլորին։", "87b98a94"]},
"OLAYLAR_P0049:1555-05-29:0":{"b": ["Մեգրելիայի (Դադիանիների) իշխանապետությունը թողնվեց օսմանյան ազդեցության գոտում", "ea54e8ea"], "d": ["Վրաստանը բաժանող Ամասիայի պայմանագրի դրույթներով Արևմտյան Վրաստանի Դադիանիների (Մեգրելիայի և Սվանեթիի) իշխանապետությունը Իմերեթիի և Գուրիայի հետ միասին թողնվեց օսմանյան ազդեցության գոտում։ Քարտեզում Մեգրելիայի կենտրոն Զուգդիդին այս օրվանից երևում է որպես օսմանցիներին ենթակա իշխանապետություն. փաստացի հնազանդության հայտարարությունը, սակայն, լինելու էր 1578 թվականին։", "1724aa10"]},
"OLAYLAR_P0049:1578-08-09:0":{"b": ["Ախալցխայի աթաբեկության անցումը օսմանյան կառավարման տակ. Ալթունկալե, Խերտվիսի և Ախալքալաք", "024bb326"], "d": ["Չըլդըրում Լալա Մուստաֆա փաշայի՝ Սեֆյան առաջապահ ուժերին հաղթելուց անմիջապես հետո վրաց աթաբեկների ձեռքին գտնվող հողերը ևս անցան օսմանյան կառավարման տակ։ Ալթունկալեն և շրջակայքը պահող Դեդիս Իմեդին իր որդիների հետ հայտնեց հնազանդություն. Արդահանի սանջակբեյը գրավեց Չըլդըրն ու Թմոգվին, իսկ օսմանյան այլ զորամասեր՝ Խերտվիսին և Ախալքալաքը։ Մանուչարին և նրա եղբորը թողնվեց մեկական սանջակ, աթաբեկության երկրի մնացած մասը կապվեց ուղղակի կառավարմանը։ Ախալցխան այնուհետև դառնալու էր նորաստեղծ Չըլդըրի էյալեթի կենտրոնը. Ստամբուլ եկած, իսլամ ընդունած և Մուստաֆա անունն առած Մանուչարը 1579 թվականի հուլիսի 1-ին նշանակվելու էր այդ էյալեթի ղեկավար։", "23731679"]},
"OLAYLAR_P0049:1595-01-01:0":{"b": ["Միքայել Քաջի արշավանքները Դանուբի ամրոցների վրա. Ռուսչուկը այրվեց, Բրաիլան գրավվեց, Սիլիստրան թալանվեց", "d0b83f6a"], "d": ["Սրբազան դաշինքին միացած Վալախիայի վոյևոդ Միքայել Քաջը 1594-95 թվականների ձմռանը հարձակվեց Դանուբի ափի՝ անմիջական օսմանյան կառավարման տակ գտնվող ամրոցների ու քաղաքների վրա։ TDV-ի Ռուսչուկի հոդվածի համաձայն՝ 1595 թվականի փետրվարին, թեև չկարողացավ վերցնել ամրոցը, գրավեց և այրեց քաղաքը։ Բրաիլայի հոդվածի համաձայն՝ գրավեց Դանուբի ձախ ափի Բրաիլան, և քաղաքը մինչև 1601 թվականը մնաց նրա ձեռքին. Մուրադ III-ի հոդվածն էլ գրում է, որ վալախական բանակը այրեց Բրաիլայի ամրոցը և հասավ մինչև Սիլիստրա։ Սիլիստրայի հոդվածում հիշատակվող մի հաշվառման գրառման համաձայն՝ վալախական բանակը 1595 թվականի գարնանը անցավ Դանուբը և թալանեց Սիլիստրան. քաղաքի ամրոցը ավերվեց և երկար ժամանակ չէր կարող օգտագործվել։ Նույն ամռանը Քոջա Սինան փաշան արշավելու էր Վալախիայի վրա։", "c115852f"]},
"OLAYLAR_P0049:1711-04-09:0":{"b": ["Սկսվեց Պրուտի արշավանքը. 1710-1711 թվականների ռուս-թուրքական պատերազմում բանակը դուրս եկավ Ստամբուլից", "3161364b"], "d": ["Ռուսաստանի հարձակումը օսմանյան հողերի վրա, ցար Պետրոսի կողմից 1700 թվականի Կոստանդնուպոլսի պայմանագրի դրույթները չկատարելը և Ղրիմի խան Դևլեթ Գիրեյի դրդումները Ահմեդ III-ին հանգեցրին Ռուսաստանին պատերազմ հայտարարելուն։ TDV-ի Ահմեդ III-ին նվիրված հոդվածի համաձայն՝ հետագայում «Պրուտի արշավանք» անունով հիշվող այս պատերազմը փաստացի սկսվեց 1711 թվականի ապրիլի 9-ին օսմանյան բանակի՝ Ստամբուլից դուրս գալով։ Բալթաջի Մեհմեդ փաշայի հրամանատարությամբ բանակը, միանալով ղրիմյան ուժերին, առաջացավ դեպի Պրուտ գետը. արշավանքը հուլիսին ավարտվելու էր ռուսական բանակի՝ Պրուտի ափին սեղմվելով։", "49618c54"]},
"OLAYLAR_P0049:1787-07-27:0":{"b": ["Վերջնագիր ռուս դեսպանին. վերջին քայլը դեպի 1787-1792 թվականների ռուս-թուրքական պատերազմ", "cb389693"], "d": ["1783 թվականին Ղրիմը Ռուսաստանին բռնակցելուց հետո շարունակվող լարվածությունը խզման հասավ, երբ պարզվեց, որ Ալեքսանդրիայի ռուսական հյուպատոսությունը Եգիպտոսի մամլուք բեյերին դրդում է օսմանցիների դեմ։ TDV-ի Աբդուլհամիդ I-ին նվիրված հոդվածի համաձայն՝ ռեիսուլքյութտաբ Սուլեյման Ֆեյզի էֆենդին 1787 թվականի հուլիսի 27-ին Ստամբուլում ռուս դեսպանին հանձնեց յոթ կետից բաղկացած վերջնագիր։ Առանց Ռուսաստանի պատասխանին սպասելու՝ որոշվեց պատերազմել, և մի քանի շաբաթվա ընթացքում այն հայտարարվեց. պատերազմի նպատակը Ղրիմը հետ վերցնելն էր։", "04debfa8"]},
"OLAYLAR_P0049:1919-04-29:0":{"b": ["Անթալիայի իտալական օկուպացիան", "328331da"], "d": ["Մուդրոսի զինադադարից հետո, մինչ Անտանտի տերությունները հաստատվում էին Անատոլիայի օկուպացիոն գոտիներում, Իտալիան ուղղվեց դեպի հարավ-արևմտյան Անատոլիա։ TDV-ի Անթալիայի հոդվածի համաձայն՝ քաղաքը և շրջակայքը, հիմնվելով զինադադարի դրույթների վրա, 1919 թվականի ապրիլի 29-ին գրավվեցին իտալացիների կողմից։ Օկուպացիան տևելու էր մոտ երկու տարի։", "41127caf"]},
"OLAYLAR_P0049:1920-02-11:0":{"b": ["Մարաշի ազատագրումը. ֆրանսիացիները դատարկեցին քաղաքը", "a57d884e"], "d": ["Անգլիացիների՝ 1919 թվականի փետրվարի 22-ին գրաված Մարաշը 1919 թվականի հոկտեմբերի 29-ին երկու պետությունների համաձայնությամբ թողնվել էր ֆրանսիացիներին։ Ֆրանսիական զորամասերում գտնվող հայերի վերաբերմունքը և ամրոցի թուրքական դրոշի իջեցումը ապստամբեցրին ժողովրդին. քաղաքում կազմակերպվեցին Իրավունքների պաշտպանության ընկերությունը և Ազգային ուժերը։ TDV-ի Քահրամանմարաշի հոդվածի համաձայն՝ բախումների վերջում ֆրանսիացիները 1920 թվականի փետրվարի 11-ին, դատարկելով քաղաքը, սկսեցին նահանջել Իսլահիեի ուղղությամբ, և Մարաշը ազատագրվեց փետրվարի 11-12-ին։ Քաղաքին 1925 թվականին տրվեց Անկախության մեդալ։", "d3bff1ef"]},
"OLAYLAR_P0049:1920-04-11:0":{"b": ["Ուրֆայի ազատագրումը. ֆրանսիական կայազորը լքեց քաղաքը", "c889488c"], "d": ["1919 թվականի մարտին անգլիացիների, իսկ մոտ յոթ ամիս անց՝ ֆրանսիացիների գրաված Ուրֆայում ժողովուրդը 1920 թվականի փետրվարի 7-ին ապստամբեց օկուպացիոն ուժերի դեմ։ TDV-ի Շանլըուրֆայի հոդվածի համաձայն՝ երկու ամիս տևած մարտերից հետո ֆրանսիացիները 1920 թվականի ապրիլի 10-ին համաձայնագրի պայմաններով ընդունեցին դատարկել Ուրֆան և հաջորդ օրը դուրս եկան քաղաքից։", "88526a6f"]},
"OLAYLAR_P0049:1920-09-28:0":{"b": ["Սկսվեց Արևելյան ճակատի գործողությունը. Քյազիմ Կարաբեքիրը հարձակման անցավ Հայաստանի դեմ", "151678df"], "d": ["Քանի որ Սևրի պայմանագիրը Էրզրումը, Տրապիզոնը, Վանը, Բիթլիսը և Բինգյոլը թողնում էր Հայաստանին, և տարածաշրջանում հայկական հարձակումներն ավելացել էին, Թուրքիայի Մեծ ազգային ժողովի կառավարությունը 1920 թվականի սեպտեմբերի 20-ին թույլատրեց գործողությունը։ TDV-ի Քյազիմ Կարաբեքիրի հոդվածի համաձայն՝ Արևելյան ճակատի հրամանատար Կարաբեքիրը, Սողանլը լեռան լեռնանցքները պահող իր զորամասերին հարձակման հրաման տալով, սեպտեմբերի 28-ին սկսեց արևելյան գործողությունը։ Գրավվեցին Սարիղամիշը, Գյոլեն և Կաղզվանը. գործողությունը մեկ ամիս անց շարունակվելու էր Կարսի ազատագրմամբ։", "add8f41a"]},
"OLAYLAR_P0049:1920-10-30:0":{"b": ["Կարսի ազատագրումը. Արևելյան ճակատի ուժերը մտան Կարս", "4e578071"], "d": ["TDV-ի Կարսի հոդվածի համաձայն՝ Քյազիմ Կարաբեքիր փաշան 1920 թվականի հոկտեմբերի 30-ին մտավ Կարս, և քաղաքն ազատագրվեց հայկական կառավարումից, որի վերահսկողությունը անգլիացիները թողել էին 1919 թվականին։ Կարաբեքիրի հոդվածը շեշտում է, որ սա Կարսի երկրորդ ազատագրումն էր. քաղաքն առաջին անգամ հայերից վերցվել էր 1918 թվականի ապրիլին։ Արևելյան ճակատի ուժերը, առաջանալով, նոյեմբերի 7-ին գրավեցին Գյումրին. պատերազմն ավարտվեց 1920 թվականի դեկտեմբերի 3-ի Ալեքսանդրապոլի պայմանագրով։", "1841f6d3"]},
"OLAYLAR_P0049:1920-11-07:0":{"b": ["Գյումրիի գրավումը. Արևելյան ճակատի ուժերն առաջացան Հայաստանի խորքը", "cfddf791"], "d": ["Կարսի ազատագրումից հետո գործողությունը շարունակող Քյազիմ Կարաբեքիր փաշայի զորամասերը 1920 թվականի նոյեմբերի 7-ին գրավեցին Գյումրին։ Զինադադարի համաձայնած հայերի հետ բանակցությունները վարվեցին Գյումրիում, և պատերազմն ավարտվեց 1920 թվականի դեկտեմբերի 3-ին ստորագրված Ալեքսանդրապոլի պայմանագրով։", "4c34b9ce"]},
"OLAYLAR_P0049:1920-11-12:0":{"b": ["Իգդիրի գրավումը", "6e952d2e"], "d": ["Արևելյան ճակատի ուժերը Գյումրին գրավելուց հինգ օր անց՝ 1920 թվականի նոյեմբերի 12-ին, գրավեցին նաև Իգդիրը։ Իգդիրը 1920 թվականի դեկտեմբերի 3-ի Ալեքսանդրապոլի պայմանագրով թողնվեց Թուրքիային։", "f96469bd"]},
"OLAYLAR_P0049:1921-02-09:0":{"b": ["Այնթապի պաշտպանության վախճանը. քաղաքը տասն ամիս դիմադրելուց հետո թողնվեց ֆրանսիացիներին", "e080af8b"], "d": ["Անգլիացիների՝ 1918 թվականի դեկտեմբերի 17-ին մտած Այնթապը 1919 թվականի նոյեմբերի 5-ին թողնվել էր ֆրանսիացիներին. Այնթապ-Քիլիս գծի առաջին դիմադրությունը ղեկավարեց Շահին բեյը։ TDV-ի Գազիանթեփի հոդվածի համաձայն՝ քաղաքի բնակչությունը 1920 թվականի ապրիլի 1-ից մինչև 1921 թվականի փետրվարի 7-ը դիմադրեց ֆրանսիական ուժերին. երբ դիմադրությունը կոտրվեց, պաշտպանության ուժերը նահանջեցին, և ֆրանսիացիները փետրվարի 9-ին տիրեցին քաղաքին։ Թուրքիայի Մեծ ազգային ժողովը օկուպացիային տասն ամիս դիմացած քաղաքին դրանից երեք օր առաջ՝ 1921 թվականի փետրվարի 6-ին, շնորհել էր ղազիի կոչում։ Այնթապը դատարկվելու էր Անկարայի պայմանագրից հետո՝ 1921 թվականի դեկտեմբերի 25-ին։", "086ee824"]},
"OLAYLAR_P0049:1921-02-23:0":{"b": ["Արդահանի և Արթվինի ազատագրումը", "b9e50d5e"], "d": ["Ալեքսանդրապոլի պայմանագրից հետո Արևելյան ճակատի ուժերն ուղղվեցին Էլվիյեի Սելասեի (երեք սանջակ)՝ Վրաստանի ձեռքին գտնվող մասի վրա։ TDV-ի Արդահանի հոդվածի համաձայն՝ վրացական և հայկական խմբերի դեմ շարունակվող պայքարի վերջում 1921 թվականի փետրվարի 23-ին Արթվինի հետ միասին ազատագրվեց նաև Արդահանի սանջակը։ Քյազիմ Կարաբեքիրի հոդվածը գրում է, որ այս քայլով հետ վերցվեցին Էլվիյեի Սելասեի հողերը, բացի Չուրուքսուի, Աջարիայի և Բաթումի կազաներից։", "1ee51ba4"]},
"OLAYLAR_P0069:1523-01-01:0":{"b": ["Ունա գետի հովտում Օստրովիցա ամրոցի նվաճումը", "5c6cc91b"], "d": ["Ֆրանկապանների և խորվաթ այլ ազնվականների ձեռքին գտնվող Օստրովիցան գտնվում էր Ունայի հովտի հյուսիսային և հարավային մասերը կապող զառիթափ լեռնաշղթայի վրա։ 1523 թվականին անցավ օսմանյան կառավարման տակ և մինչև 1878 թվականը օսմանյան կայազոր ուներ։ Ամրոցը իր իսկական նշանակությունը ձեռք բերեց Կառլովիցից (1699) հետո. Վենետիկի և Ավստրիայի սահմանին մոտ լինելու պատճառով ընդարձակվեց և դարձավ Ստարա Օստրովիցայի կապետանության կենտրոնը. Կուլեն Վակուֆ ավանը 18-րդ դարի սկզբին հիմնվեց նրա ստորոտին։", "0978b370"]},
"OLAYLAR_P0069:1527-05-01:0":{"b": ["Ուդբինա և Կրբավա ամրոցների նվաճումը. Լիկան անցնում է օսմանյան կառավարման տակ", "5fe329d3"], "d": ["Կրբավայի դաշտը 1524 թվականին ամայացել էր, Ուդբինայում մնացել էր միայն Կարլովիչի կայազորը։ Կարլովիչը 1527 թվականի ապրիլին ամրոցի առաջ տարավ վերջին հաղթանակը, բայց մայիսի վերջին Ուդբինան Մրսինյ և Կոմիչ ամրոցների հետ միասին անցավ Բոսնիայի փաշայի ձեռքը։ Նույն տարում Գոսպիչի շրջանը տրվեց Սենկովիչ աղաներին։ Լիկան և Կրբավան այնուհետև դարձան Օբրովաց կենտրոնով, 1580 թվականին Կրկա անվանումն ստացած սանջակի մաս։", "0e759e1a"]},
"OLAYLAR_P0069:1592-01-01:0":{"b": ["Դրեժնիկի և Դրեժնիկի ժուպանիայի վերջնական անցումը օսմանյան կառավարման տակ", "6624ad14"], "d": ["1323 թվականից Ֆրանկապանների ձեռքին գտնվող Դրեժնիկը 1578 թվականին ժամանակավորապես պահել էին օսմանցիները։ 1592 թվականին ամրոցը և Դրեժնիկի ողջ ժուպանիան վերջնականապես անցան օսմանյան կառավարման տակ. նույն տարում ընկավ նաև Բիհաչը։ Դրեժնիկը 18-րդ դարում ենթակա էր Օստրոժացի կապետանությանը։", "b41efb59"]},
"OLAYLAR_P0069:1636-01-01:0":{"b": ["Ցետին ամրոցի գրավումը օսմանցիների կողմից", "98815f97"], "d": ["16-րդ դարի կեսից Սլունյի շրջանի՝ օսմանցիների դեմ պաշտպանության բանալի ամրոցը՝ Ցետինը, բազմիցս պաշարվելուց հետո 1636 թվականին անցավ օսմանյան կառավարման տակ։ Այս առաջին օսմանյան շրջանը տևեց երկու տարի։", "44a52e6e"]},
"OLAYLAR_P0069:1638-01-01:0":{"b": ["Ցետին ամրոցի վերադարձը Հաբսբուրգյան կողմին", "690f9f84"], "d": ["1636 թվականին օսմանյան ձեռքն անցած Ցետինը 1638 թվականին վերադարձավ խորվաթա-հաբսբուրգյան սահմանային պաշտպանությանը և այդպես մնաց մինչև 1670 թվականը։", "8f16b3ec"]},
"OLAYLAR_P0069:1670-01-01:0":{"b": ["Ցետինը կրկին դարձավ օսմանյան ամրոց", "e1750675"], "d": ["Ցետինը 1670 թվականին կրկին դարձավ օսմանյան ամրոց և 18-րդ դարում հիմնովին ամրացվեց. միջնադարյան ամրոցը շրջապատվեց բաստիոններով պարիսպներով։ Ամրոցը մինչև 1790 թվականը պահեց Բոսնիայի սահմանամերձ գոտու հյուսիս-արևմտյան ծայրը։", "3cf8713d"]},
"OLAYLAR_P0069:1689-01-01:0":{"b": ["Լիկայի և Կրբավայի կորուստը. Ուդբինան և Գոսպիչն անցան Հաբսբուրգյան սահմանային ուժերի ձեռքը", "01277a38"], "d": ["Վիեննայի ջախջախումից հետո շարունակվող պատերազմում խորվաթ սահմանապահ զորամասերը Կարլովացի գեներալ Հերբերշտեյնի հրամանատարությամբ 1689 թվականին գրավեցին Ուդբինան. Գոսպիչը նույն տարում նույնպես դուրս եկավ օսմանյան կառավարումից։ Ավարտվեց ավելի քան 160 տարի տևած օսմանյան Լիկան. դատարկված տեղերը բնակեցվեցին նոր խորվաթ բնակչությամբ, և Ուդբինան մինչև Սիստովայի հաշտությունը (1791) մնաց օսմանցիների դեմ սահմանային պաշտպանության կարևոր ամրոցներից մեկը։", "bde1a0dc"]},
"OLAYLAR_P0069:1788-01-01:0":{"b": ["Դրեժնիկի գրավումը Ավստրիայի կողմից. Դուբիցայի պատերազմի արևմտյան ճակատը", "05d5e5f1"], "d": ["1788-1791 թվականների օսմանա-ավստրիական պատերազմում Հաբսբուրգյան ուժերը գրավեցին Բիհաչից արևմուտք գտնվող Դրեժնիկը։ Սիստովայի պայմանագրի 4-րդ հոդվածով Դրեժնիկը և Ցետինը մնացին Հաբսբուրգյան կառավարման տակ և այլևս չվերադարձան Բոսնիային։", "30f8f200"]},
"OLAYLAR_P0069:1790-01-01:0":{"b": ["Ցետին ամրոցի գրավումը Ավստրիայի կողմից", "df182480"], "d": ["1790 թվականին Հաբսբուրգյան բանակը հարձակվեց Ցետինի, Բուժիմի և Վելիկա Կլադուշայի վրա և գրավեց Ցետինը։ Բոսնիայի կուսակալի հայտարարած զորահավաքը և հակահարձակումը չկարողացան հետ վերցնել ամրոցը. Սիստովայի պայմանագրի 4-րդ հոդվածը Ցետինը թողեց Հաբսբուրգներին։ Բոսնիացի սահմանապահները 1809 և 1813 թվականներին կարճատև հարձակումներով կրկին գրավեցին ամրոցը։", "fc69baec"]},
"OLAYLAR_SENUSI_0919:1551-07-01:0":{"b": ["Էրդելի Բանատի ամրոցների (Թեմեշվար, Լիպպա, Լուգոշ, Կարանշեբեշ) հանձնումը Հունգարիայի թագավոր Ֆերդինանդին", "0e354976"], "d": ["1551 թվականին գեներալ Կաստալդոյի հրամանատարությամբ Հաբսբուրգյան բանակը մտավ Էրդել. թագուհի Իզաբելլան և նրա որդին ստիպված եղան հրաժարվել Հունգարիայի գահի նկատմամբ իրենց իրավունքներից։ Մարտինուցին Կաստալդոյի հավանությամբ 1551 թվականի հուլիսի կեսին ուղարկեց Բատորի Էնդրեին, որպեսզի Թեմեշվար, Լիպպա, Շոյմոշ, Կարանշեբեշ, Լուգոշ, Բեչե, Բեչկերեկ և Չանադ ամրոցները ընդունի Ֆերդինանդի անունից։ Այսպիսով օսմանյան հովանու տակ գտնվող Էրդելի հարավային ամրոցներն անցան Հաբսբուրգների ձեռքը. Կանունի Սուլեյմանի 1551-1552 թվականների արշավանքները դրա պատասխանն են։", "420ca62a"]},
"OLAYLAR_SENUSI_0919:1554-04-07:0":{"b": ["Պետրովիչ Պետերի նշանակումը Լուգոշի և Կարանշեբեշի սանջակբեյ", "bcbe73e4"], "d": ["Իզաբելլայի և Պետրովիչի համառ խնդրանքով Կանունի Սուլեյմանը որոշեց փոքրիկ Յանոշ Զիգմոնդին վերադարձնել Էրդել։ 1554 թվականի ապրիլի 7-ին Հալեպից գրած նամակով նա էրդելցիներին հրամայեց երեխային վերադարձնել իր երկիր, իսկ Վալախիայի և Մոլդովայի վոյևոդներին պատվիրեց այդ գործում օգնել Պետրովիչին, որին նույն ժամանակ նշանակեց Լուգոշի և Կարանշեբեշի սանջակբեյ։ Այսպիսով 1552 թվականին գրավված Լուգոշը որպես օսմանյան սանջակ տրվեց Պետրովիչին։", "6c5be465"]},
"OLAYLAR_SENUSI_0919:1596-05-10:0":{"b": ["Լիպպայի պաշարման վերացումը. Լուգոշի բանի հարձակումը Թեմեշվարի վրա", "be03430e"], "d": ["1596 թվականի գարնանը Թեմեշվարի փաշան պաշարեց Լիպպան։ Մայիսի 10-ից 11-ը գիշերը, Էրդելի Լուգոշի բան Պալատիչ Դյորդի հրամանով, Բուդայ Դյորդի զինվորները հարձակվեցին Թեմեշվարի արվարձանների վրա և հրկիզեցին դրանք. ամրոցում Բորբեյ Դյորդի՝ բոլոր թնդանոթները կրակելու հրամանը նույնպես փաշային համոզեց, որ օգնություն է եկել։ Փաշան մայիսի 11-ին, հեռանալով Լիպպայի մոտից, շտապեց պաշտպանել իր կենտրոնը։ Լուգոշն այդ ժամանակ Էրդելի իշխանապետության ձեռքին էր։", "07e2cb97"]},
"OLAYLAR_SENUSI_0919:1688-01-01:0":{"b": ["Օրշովայի գրավումը Վետերանիի հրամանատարությամբ ավստրիական ուժերի կողմից", "1b4a4f6c"], "d": ["1688 թվականի արշավանքում գեներալ Վետերանին, Կարանշեբեշը գրավելուց հետո, շարժվեց Օրշովայի վրա և գրավեց նաև այն։ Աղբյուրում գրավման օրը չկա. օգտագործվել է տարվա հիմնական ամսաթիվը՝ 1688 թվականի հունվարի 1-ը։", "1dfe042e"]},
"OLAYLAR_SENUSI_0919:1689-07-15:0":{"b": ["Օրշովայի վերագրավումը Թյոքյոլիի և օսմանյան ուժերի կողմից", "c5645da9"], "d": ["1688 թվականին Վետերանիի գրաված Օրշովայի վրա Վետիսլանի գրավումից հետո շարժվեցին Թյոքյոլին և օսմանյան փաշաները։ Աննշան բախումներից հետո Թյոքյոլին 1689 թվականի հուլիսի 15-ին մտավ Օրշովա։ Վտանգի լուրով եկած Հեյսլերը, տեսնելով, որ հակառակ ուժը լավ հագեցած է ռազմամթերքով և նավերով, նահանջեց Էրդելը պաշտպանելու համար։ Օգոստոսին Էրբևիլի հարձակումը քաղաքի առաջ նույնպես չկարողացավ հետ վերցնել Օրշովան։", "6d469bdd"]},
"OLAYLAR_SENUSI_0919:1691-01-01:0":{"b": ["Լուգոշի սանջակն անցավ Հաբսբուրգյան օկուպացիայի տակ (1691-1695)", "c8bcd6bd"], "d": ["Լուգոշի սանջակը 1691-1695 թվականներին մնաց Հաբսբուրգյան (գերմանական) օկուպացիայի տակ. Մուստաֆա II-ը 1695 թվականի սեպտեմբերի 22-ին վերանվաճեց այն։ Հին գրառման մեջ 1689-1695 թվականները հայտարարված բացթողում էին. 1691-1695 հատվածն այժմ ներկվում է որպես Հաբսբուրգյան, իսկ 1689-1691-ը մնում է բացթողում։ Ամսաթիվը վերցված է միայն տարով։", "053d32c8"]},
"OLAYLAR_SENUSI_0919:1716-10-18:0":{"b": ["Լուգոշի ամրոցն անցավ Հաբսբուրգյան կառավարման տակ", "6a9d401f"], "d": ["Թեմեշվարի էյալեթին ենթակա Լուգոժ սանջակային ամրոցը 1695 թվականից օսմանյան ձեռքին էր. 1716 թվականի պաշարման վերջում էյալեթի կենտրոնի հանձնումով այն թողնվեց Հաբսբուրգյան միապետությանը։ Հին գրառումը փոխանցումը դնում էր տարվա հիմնական ամսաթվի՝ 1716 թվականի հունվարի 1-ի վրա։", "ab78a026"]},
"OLAYLAR_SENUSI_0919:1717-01-01:0":{"b": ["Օրշովայի գրավումը Հաբսբուրգյան բանակի կողմից (1717 թվականի արշավանք)", "7a4faffe"], "d": ["1717 թվականի արշավանքում գեներալ Սպլենյին օգոստոսի 27-ին հասավ Օրշովա և հեշտությամբ գրավեց քաղաքը. այսպիսով Օրշովան, որ 1716-ին Մերսին չէր կարողացել գրավել, անցավ Հաբսբուրգների ձեռքը։ Շրջակա դանուբյան ափի բջիջները (ներառյալ սերբական ափի Ջերդապի հատվածը), քանի որ կապված են ամենամոտ բնակավայրային կետի՝ Օրշովայի հետ, ներկվում են նրա տիրոջ գույնով։ Ամսաթիվը վերցված է միայն տարով. ճշգրիտ օրը հաստատված չէ։", "724e03d5"]},
"OLAYLAR_SENUSI_0919:1738-05-08:0":{"b": ["Օրշովայի պալանկայի անցումը Օսմանյան պետությանը. կայազորի նահանջը Ադակալե", "de759b16"], "d": ["1738 թվականի արշավանքի սկզբում Վիդինի մուհաֆիզ Հաջի Մեհմեդ փաշան հարձակվեց Դանուբի ափին գտնվող Erzsébet ամրաշինության վրա։ Մայիսի 8-ի կեսօրից հետո 4-5 հազար սիփահիներից բաղկացած ջոկատը Դանուբի ձախ ափով շարժվեց դեպի Օրշովա և հարձակվեց Օրշովայի պալանկայի վրա. մոտ հարյուր զոհ տված ավստրիական կայազորը նահանջեց Նոր Օրշովա, այսինքն՝ Ադակալե կղզի-ամրոցը։ Հուլիսի Մեհադիայի բախումներից հետո Ադակալեն ևս 1738 թվականի օգոստոսին անցավ օսմանյան ձեռքը. 1739 թվականի Բելգրադի պայմանագիրը ճանաչեց այս վիճակը։", "70ee9650"]},
"OLAYLAR_SERHAT:1428-01-01:0":{"b": ["Մուրադ II-ը գրավեց Կրուշևացը, Նիշն ու Պիրոտը վերադարձան Օսմանյան պետությանը", "54af926a"], "d": ["Սերբ դեսպոտ Ստեֆան Լազարևիչի անժառանգ մահից (1427) հետո Մուրադ II-ը, հենվելով Բայազիդ I Յըլդըրըմի՝ սերբ արքայադստեր հետ ամուսնության վրա և հայտարարելով, որ ինքը Սերբիայի օրինական ժառանգորդն է, գործի անցավ և գրավեց Կրուշևացը (1428)։ Նույն տարում, Լազարևիչի մահից հետո, օսմանցիները հետ վերցրին նաև Պիրոտի ամրոցը. քաղաքը 1412 թվականին գրավել էր Ստեֆանը և պաշտպանել Մուսա Չելեբիի դեմ։ TDV-ի «nis» հոդվածի համաձայն՝ օսմանցիները նույն տարում (հիջ. 831/1428) հետ վերցրին նաև Նիշը։ Այսպիսով Մեծ Մորավայի և Նիշավայի հովիտները կապող գիծն անցավ օսմանյան վերահսկողության տակ։", "01c87afb"]},
"OLAYLAR_SERHAT:1443-01-01:0":{"b": ["Խաչակիրների բանակը գրավեց Պիրոտը. «Երկար արշավանքի» Նիշավայի թևը", "fdf6140c"], "d": ["Թագավոր Վլադիսլավի և սերբ դեսպոտ Գեորգ Բրանկովիչի գլխավորած խաչակրաց բանակը 1443 թվականին գրավեց Պիրոտը։ Նույն արշավանքի շարունակությամբ օսմանյան ուժերը նոյեմբերին ջախջախվելու էին Իզլադիի լեռնանցքում։ Պիրոտը Սեգեդի պայմանագրից (1444) հետո Մուրադ II-ի կողմից կրկին տրվեց սերբերին, բայց 1456 թվականին, Գեորգ Բրանկովիչի մահից հետո, անցավ օսմանցիներին։", "f56645a4"]},
"OLAYLAR_SERHAT:1458-01-01:0":{"b": ["Կրուշևացի շրջանում հաստատվեց վերջնական օսմանյան տիրապետությունը", "9715382a"], "d": ["1444 թվականին հունգար պատվիրակների հետ կնքված պայմանագրի արդյունքում Բրանկովիչին թողնված Կրուշևացը Վառնայի հաղթանակին հաջորդած տարիներին կրկին անցավ թուրքական տիրապետության տակ։ Քաղաքի այս երկրորդ նվաճումը վավերագրված է ոչ թե պատերազմի, այլ ֆինանսական գրառումով. Կրուշևացին ենթակա որոշ գյուղերի թիմարային գրառումները թվագրվում են 1453-ի վերջ / 1454-ի սկիզբ. բայց դա միայն գյուղերի վկայություն է. 1454 թվականին օսմանյան ուժերը ջախջախվեցին Կրուշևացի մոտ, իսկ 1455-ին Կրուշևացը որպես սահման թողնվեց Բրանկովիչին։ Ըստ TDV-ի՝ շրջանում վերջնական օսմանյան տիրապետությունը հաստատվեց 1458 թվականին։", "2b6aba24"]},
"OLAYLAR_SESSIZBORC0919:1349-01-01:0":{"b": ["Մորեայի դեսպոտության հիմնադրումը. Մանուել Կանտակուզենոսը Միստրասում", "87660b82"], "d": ["Բյուզանդական կայսր Հովհաննես Կանտակուզենոսը իր որդի Մանուելին Մորեայում տվեց առանձին կառավարման շրջան. այսպես ծնվեց Միստրաս կենտրոնով Մորեայի դեսպոտությունը։ Մանուելը կառավարեց մինչև 1380 թվականը. այդ շրջանում բյուզանդական մշակույթն ու արվեստը հատկապես զարգացան Միստրասում։ Դեսպոտությունը տևեց մինչև 1460 թվականը՝ Ֆաթիհի նվաճումը։", "f5596d5e"]},
"OLAYLAR_SESSIZBORC0919:1430-01-01:0":{"b": ["Դեսպոտ Կոնստանտինը Պատրասը խլեց ֆրանկներից", "cb0dd18c"], "d": ["Մորեայի դեսպոտ Կոնստանտինը (1449-ին՝ Բյուզանդիայի վերջին կայսրը) Պատրասը հետ վերցրեց լատիններից. այսպիսով թերակղզու հյուսիս-արևմուտքի այս կարևոր նավահանգիստը ևս միացավ դեսպոտությանը։ Պատրասը 1458 թվականին, Ֆաթիհի Մորեայի արշավանքի ժամանակ, անցավ օսմանյան տիրապետության տակ։", "98b8dff0"]},
"OLAYLAR_SESSIZBORC0919:1448-01-01:0":{"b": ["Ստեպան Վուկչիչ-Կոսաչան՝ «Սուրբ Սավայի դուքս». Հերցեգովինայի ծնունդը", "cc67061f"], "d": ["Հումը և Տրեբինյեն մեկ բեյության մեջ միավորած Ստեպան Վուկչիչ-Կոսաչան ապստամբեց Բոսնիայի թագավորի դեմ և իրեն հռչակեց «Սուրբ Սավայի հերցոգ (դուքս)». տիտղոսը նրան 1448 թվականին տվեց կայսր Ֆրիդրիխ III-ը։ Հերցեգովինա («Հերցոգի երկիրը») անունը ծագում է այս տիտղոսից։ Հերցեգովինան 1466 թվականից սկսած մաս-մաս անցավ Օսմանյան պետությանը, 1470 թվականին դարձավ սանջակ, իսկ մնացած հողերը միացան 1482 թվականի սկզբին։", "e6a77d9c"]},
"OLAYLAR_SESSIZBORC0919:1525-04-08:0":{"b": ["Կրակովի հաշտությունը. Տևտոնական օրդենի պետությունը վերածվեց Պրուսիայի դքսության", "78666ddd"], "d": ["Տևտոնական ասպետների մեծ մագիստրոս Ալբրեխտ Բրանդենբուրգցին, Լեհաստանի դեմ օգնություն չգտնելով, ստորագրեց Կրակովի հաշտությունը։ Օրդենի պետությունը (Ordensstaat) դարձավ Լեհաստանի գերիշխանության տակ գտնվող, Բրանդենբուրգյան հարստությանն անցած ժառանգական և աշխարհիկ դքսություն։ Կենտրոնը Քյոնիգսբերգն էր. Ալբրեխտը 1544 թվականին այստեղ հիմնեց Ալբերտինա համալսարանը։ Դքսությունը 1701 թվականին վերածվեց Պրուսիայի թագավորության։", "d38ad9a3"]},
"OLAYLAR_SESSIZBORC0919:1918-11-12:0":{"b": ["Ավստրիայի Հանրապետության հռչակումը. Հաբսբուրգյան միապետության վախճանը", "c84f316c"], "d": ["Կայսր Կարլ I-ի՝ նոյեմբերի 11-ին պետական գործերից հեռանալու հաջորդ օրը Ժամանակավոր ազգային ժողովն ընդունեց պետության և կառավարման ձևի մասին օրենքը, և հռչակվեց հանրապետությունը։ Հաբսբուրգյան Ավստրիայի տեղը գրավեց Վիեննա կենտրոնով Առաջին հանրապետությունը։ Այս հռչակմամբ Վիեննան, Լինցը, Զալցբուրգը, Ինսբրուկը, Կլագենֆուրտը, Բրեգենցը և գերմանա-ավստրիական մյուս քաղաքները դարձան Ավստրիայի Հանրապետության (Deutschösterreich) հողը։", "2dcc1399"]}
});
